import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../../lib/cn";

const buttonVariants = cva(
  [
    "inline-flex items-center justify-center whitespace-nowrap gap-2",
    // font-semibold: content-button's Named Style is intended semibold (600)
    // per theme.css, but font-content-button only resolves font-family (see
    // Text.tsx's file-level comment for the full explanation) — the
    // decomposed classes alone never applied the weight. Fixed 2026-07-23
    // (PR #44 review finding), same gap as Tabs.tsx's active-tab state.
    "rounded-sm text-content-button font-content-button font-semibold leading-content-button tracking-content-button",
    "transition",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
    "disabled:pointer-events-none data-[disabled]:pointer-events-none",
  ],
  {
    variants: {
      variant: {
        default: "focus-visible:ring-filigran-brand-primary",
        destructive: "focus-visible:ring-feedback-error-primary",
        ia: "focus-visible:ring-filigran-ia-secondary",
        highlight: "focus-visible:ring-filigran-tonic-primary",
      },
      priority: {
        primary:
          "disabled:bg-elevation-disabled disabled:text-default-disabled disabled:border-transparent data-[disabled]:bg-elevation-disabled data-[disabled]:text-default-disabled data-[disabled]:border-transparent",
        secondary: [
          "border",
          "disabled:text-default-disabled disabled:border-current data-[disabled]:text-default-disabled data-[disabled]:border-current",
        ],
        tertiary: "disabled:text-default-disabled data-[disabled]:text-default-disabled",
      },
      size: {
        sm: "h-6 px-2",
        md: "h-9 px-4",
      },
    },
    compoundVariants: [
      // default × primary
      {
        variant: "default",
        priority: "primary",
        className:
          "bg-filigran-brand-primary text-negative-primary hover:bg-filigran-brand-tertiary active:bg-filigran-brand-tertiary",
      },
      // default × secondary
      {
        variant: "default",
        priority: "secondary",
        className:
          "border-elevation-default text-filigran-brand-primary hover:bg-filigran-brand-primary-transparency active:bg-filigran-brand-primary-transparency",
      },
      // default × tertiary
      {
        variant: "default",
        priority: "tertiary",
        className:
          "text-filigran-brand-primary hover:bg-filigran-brand-primary-transparency active:bg-filigran-brand-primary-transparency",
      },
      // destructive × primary
      {
        variant: "destructive",
        priority: "primary",
        className:
          "bg-feedback-error-primary text-negative-primary hover:bg-feedback-error-secondary active:bg-feedback-error-secondary",
      },
      // destructive × secondary
      {
        variant: "destructive",
        priority: "secondary",
        className:
          "border-feedback-error-secondary text-feedback-error-primary hover:bg-feedback-error-secondary-transparency active:bg-feedback-error-secondary-transparency",
      },
      // destructive × tertiary
      {
        variant: "destructive",
        priority: "tertiary",
        className:
          "text-feedback-error-primary hover:bg-feedback-error-secondary-transparency active:bg-feedback-error-secondary-transparency",
      },
      // ia × secondary (no primary per RULE-04) — gradient border + text handled in component
      {
        variant: "ia",
        priority: "secondary",
        className:
          "border-transparent hover:bg-filigran-ia-secondary-transparency active:bg-filigran-ia-secondary-transparency",
      },
      // ia × tertiary
      {
        variant: "ia",
        priority: "tertiary",
        className:
          "hover:bg-filigran-ia-secondary-transparency active:bg-filigran-ia-secondary-transparency",
      },
      // highlight × secondary (no primary per RULE-04) — gradient border + text handled in component
      {
        variant: "highlight",
        priority: "secondary",
        className:
          "border-transparent hover:bg-filigran-brand-primary-transparency active:bg-filigran-brand-primary-transparency",
      },
      // highlight × tertiary
      {
        variant: "highlight",
        priority: "tertiary",
        className:
          "hover:bg-filigran-brand-primary-transparency active:bg-filigran-brand-primary-transparency",
      },
    ],
    defaultVariants: {
      variant: "default",
      priority: "primary",
      size: "md",
    },
  },
);

function Spinner({ className }: { className?: string }) {
  return (
    <svg
      className={cn("animate-spin h-4 w-4", className)}
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
      aria-hidden="true"
    >
      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
      />
    </svg>
  );
}

export interface ButtonProps
  extends React.ComponentPropsWithoutRef<"button">, VariantProps<typeof buttonVariants> {
  /** Radix asChild — merges Button styles onto the child element (e.g. <a>, <Link>). Gradient text (ia/highlight) is not applied automatically; apply text-gradient-* on your child if needed. */
  asChild?: boolean;
  /** Icon before the label (ignored when asChild is true — Slot cannot inject wrapper elements) */
  startIcon?: React.ReactNode;
  /** Icon after the label (ignored when asChild is true — Slot cannot inject wrapper elements) */
  endIcon?: React.ReactNode;
  /** Loading state — disables the control and sets aria-busy (spinner is only rendered when asChild is false) */
  loading?: boolean;
  /** Takes the full width of the parent container */
  fullWidth?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      priority,
      size,
      asChild = false,
      startIcon,
      endIcon,
      loading = false,
      fullWidth = false,
      disabled,
      children,
      ...props
    },
    ref,
  ) => {
    const isDisabled = disabled || loading;

    const resolvedVariant = variant ?? "default";
    const resolvedPriority = priority ?? "primary";
    // RULE-04: IA/Highlight have no primary — coerce to secondary
    const enforcedPriority =
      (resolvedVariant === "ia" || resolvedVariant === "highlight") &&
      resolvedPriority === "primary"
        ? "secondary"
        : resolvedPriority;
    const isGradientType = resolvedVariant === "ia" || resolvedVariant === "highlight";
    const isGradientText =
      isGradientType &&
      (enforcedPriority === "secondary" || enforcedPriority === "tertiary") &&
      !isDisabled;
    const isGradientBorder = isGradientType && enforcedPriority === "secondary" && !isDisabled;

    const gradientBorderClass = isGradientBorder
      ? resolvedVariant === "highlight"
        ? "gradient-border-focus"
        : "gradient-border-ia"
      : undefined;

    const labelGradientClass = isGradientText
      ? resolvedVariant === "highlight"
        ? "text-gradient-focus"
        : "text-gradient-ia"
      : undefined;

    // When asChild, Slot merges all our props onto the single child element
    // so we must NOT wrap children in extra elements.
    // Note: gradient text (ia/highlight) is not applied here because
    // text-gradient-* sets color:transparent + background-clip:text which
    // breaks if the child has nested elements (they inherit transparent color
    // but not the background-clip). Consumers needing gradient text on asChild
    // must apply the utility on their child element directly.
    if (asChild) {
      return (
        <Slot
          className={cn(
            buttonVariants({ variant, priority: enforcedPriority, size }),
            gradientBorderClass,
            fullWidth && "w-full",
            className,
          )}
          ref={ref}
          data-disabled={isDisabled ? "" : undefined}
          aria-disabled={isDisabled ? true : undefined}
          aria-busy={loading || undefined}
          {...props}
          {...(isDisabled
            ? {
                onClick: (e: React.MouseEvent) => e.preventDefault(),
                onKeyDown: (e: React.KeyboardEvent) => {
                  if (e.key === "Enter" || e.key === " ") e.preventDefault();
                },
              }
            : {})}
        >
          {children}
        </Slot>
      );
    }

    return (
      <button
        className={cn(
          buttonVariants({ variant, priority: enforcedPriority, size }),
          gradientBorderClass,
          fullWidth && "w-full",
          className,
        )}
        ref={ref}
        disabled={isDisabled}
        data-disabled={isDisabled ? "" : undefined}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading ? (
          <>
            <Spinner />
            <span className={labelGradientClass}>{children}</span>
            <span role="status" className="sr-only">
              Loading…
            </span>
          </>
        ) : (
          <>
            {startIcon && (
              <span className="inline-flex shrink-0" aria-hidden="true">
                {startIcon}
              </span>
            )}
            <span className={labelGradientClass}>{children}</span>
            {endIcon && (
              <span className="inline-flex shrink-0" aria-hidden="true">
                {endIcon}
              </span>
            )}
          </>
        )}
      </button>
    );
  },
);

Button.displayName = "Button";

export { buttonVariants };
