import * as React from "react";
import * as TabsPrimitive from "@radix-ui/react-tabs";

import { cn } from "../../lib/cn";
import { Icon } from "../icon";

// ── Tabs Root ────────────────────────────────────────────────────────────────

export interface TabsProps extends React.ComponentPropsWithoutRef<typeof TabsPrimitive.Root> {}

/**
 * Defaults `activationMode` to "manual" (arrow keys move focus only; the
 * focused tab activates on Enter/Space or click) instead of Radix's own
 * "automatic" default (arrow-key focus alone activates the tab). Aligns with
 * this design system's actual shipped behavior (MUI Tabs, OpenCTI) — still
 * overridable via an explicit `activationMode` prop for call sites that want
 * automatic activation.
 */
const Tabs = React.forwardRef<React.ElementRef<typeof TabsPrimitive.Root>, TabsProps>(
  ({ activationMode = "manual", ...props }, forwardedRef) => (
    <TabsPrimitive.Root ref={forwardedRef} activationMode={activationMode} {...props} />
  ),
);
Tabs.displayName = TabsPrimitive.Root.displayName;

// ── TabsList ─────────────────────────────────────────────────────────────────

/**
 * Merges any number of refs (forwarded + internal) onto the same DOM node.
 * Needed here because the forwarded ref must keep resolving to the real
 * role="tablist" node (public contract, unchanged) while the component also
 * needs its own ref to that same node to measure/drive scroll overflow.
 * Not memoized: `refs` is a fresh array on every call anyway (rest params),
 * so a useCallback wrapper would just recompute every render for no benefit.
 */
function mergeRefs<T>(...refs: Array<React.Ref<T> | undefined>): React.RefCallback<T> {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") {
        ref(node);
      } else if (ref && typeof ref === "object") {
        (ref as React.MutableRefObject<T | null>).current = node;
      }
    }
  };
}

/** Fraction of the visible track width scrolled per arrow-button click. */
const SCROLL_STEP_RATIO = 0.8;

export interface TabsListProps extends React.ComponentPropsWithoutRef<typeof TabsPrimitive.List> {
  /**
   * Optional content aligned to the right of the tab bar (secondary actions,
   * status text…). Rendered as a DOM **sibling** of the tablist, never as a
   * child — see the ARIA note in Tabs.meta.ts (`aria-required-children`).
   */
  actions?: React.ReactNode;
}

const TabsList = React.forwardRef<React.ElementRef<typeof TabsPrimitive.List>, TabsListProps>(
  ({ className, actions, children, ...props }, forwardedRef) => {
    const listRef = React.useRef<React.ElementRef<typeof TabsPrimitive.List>>(null);
    // Memoized on forwardedRef alone (listRef is a stable useRef identity) so
    // the merged callback doesn't change identity every render — otherwise
    // React would detach/reattach the consumer's ref on every render.
    const mergedRef = React.useMemo(() => mergeRefs(forwardedRef, listRef), [forwardedRef]);
    const leftArrowRef = React.useRef<HTMLButtonElement>(null);
    const rightArrowRef = React.useRef<HTMLButtonElement>(null);

    const [canScrollLeft, setCanScrollLeft] = React.useState(false);
    const [canScrollRight, setCanScrollRight] = React.useState(false);

    const updateScrollState = React.useCallback(() => {
      const node = listRef.current;
      if (!node) return;
      const { scrollLeft, scrollWidth, clientWidth } = node;
      const nextCanScrollLeft = scrollLeft > 0;
      // 1px tolerance for sub-pixel layout rounding.
      const nextCanScrollRight = scrollLeft + clientWidth < scrollWidth - 1;

      // An arrow button is conditionally mounted — when it's about to
      // disappear (canScroll* flipping to false) while it still holds
      // keyboard focus, the browser would otherwise drop focus to <body>
      // on unmount (no visible ring, screen readers lose their place).
      // Redirect focus to the tablist first: Radix's roving-focus-group
      // intercepts focus on the list container and hands it to the
      // current trigger, so this always lands on a real, stable tab.
      if (!nextCanScrollLeft && document.activeElement === leftArrowRef.current) {
        node.focus();
      }
      if (!nextCanScrollRight && document.activeElement === rightArrowRef.current) {
        node.focus();
      }

      setCanScrollLeft(nextCanScrollLeft);
      setCanScrollRight(nextCanScrollRight);
    }, []);

    // Re-measure after every render (covers trigger add/remove) — cheap for
    // a tab bar and avoids a MutationObserver just to watch child changes.
    React.useEffect(() => {
      updateScrollState();
    });

    React.useEffect(() => {
      const node = listRef.current;
      if (!node) return undefined;

      node.addEventListener("scroll", updateScrollState, { passive: true });
      window.addEventListener("resize", updateScrollState);
      // Catches container-level resizes (e.g. a sidebar collapsing) that
      // don't fire a window resize event. Optional: runtimes without
      // ResizeObserver (older Safari, some embedded WebViews) still get
      // correct overflow updates from the scroll/resize listeners above —
      // this is an enhancement, not the only mechanism, so it's safe to skip.
      const resizeObserver =
        typeof ResizeObserver !== "undefined" ? new ResizeObserver(updateScrollState) : undefined;
      resizeObserver?.observe(node);

      return () => {
        node.removeEventListener("scroll", updateScrollState);
        window.removeEventListener("resize", updateScrollState);
        resizeObserver?.disconnect();
      };
    }, [updateScrollState]);

    const scrollByStep = (direction: -1 | 1): void => {
      const node = listRef.current;
      if (!node) return;
      node.scrollBy({
        left: direction * node.clientWidth * SCROLL_STEP_RATIO,
        behavior: "smooth",
      });
    };

    const arrowButtonClassName = cn(
      "self-center shrink-0 inline-flex items-center justify-center",
      "size-8 rounded-sm transition",
      "text-default-secondary hover:bg-filigran-brand-primary-transparency",
      "focus-visible:outline-none focus-visible:ring-2 ring-focus",
      "focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
    );

    return (
      // Visual bar: border + full width now live here (moved off the
      // tablist below) so the border spans tabs *and* actions. Carries the
      // consumer className — non-regression for existing TabsList usage.
      <div
        className={cn("flex items-stretch w-full border-b-2 border-elevation-subtle", className)}
      >
        {canScrollLeft && (
          <button
            ref={leftArrowRef}
            type="button"
            aria-label="Scroll tabs left"
            onClick={() => scrollByStep(-1)}
            className={arrowButtonClassName}
          >
            <Icon name="chevron-left" size={16} />
          </button>
        )}

        {/* Fade anchor: relative wrapper sized exactly to the scrollable
            tablist so the fade overlays sit flush on its edges, never
            inside role="tablist" itself. */}
        <div className="relative flex-1 min-w-0">
          <TabsPrimitive.List
            ref={mergedRef}
            className="flex flex-row items-stretch w-full h-full overflow-x-auto scrollbar-hide scroll-smooth"
            {...props}
          >
            {children}
          </TabsPrimitive.List>

          {/* Decorative truncation cues — never the sole overflow signal
              (arrows + the visually clipped tab also carry it, WCAG 1.4.1).
              Opacity capped at 20%: computed so tab text blended under the
              fade never drops below 4.5:1 (see Tabs.meta.ts notes). */}
          {canScrollLeft && (
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 left-0 w-8 bg-linear-to-r from-fade-overlay to-transparent"
            />
          )}
          {canScrollRight && (
            <div
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 right-0 w-8 bg-linear-to-l from-fade-overlay to-transparent"
            />
          )}
        </div>

        {canScrollRight && (
          <button
            ref={rightArrowRef}
            type="button"
            aria-label="Scroll tabs right"
            onClick={() => scrollByStep(1)}
            className={arrowButtonClassName}
          >
            <Icon name="chevron-right" size={16} />
          </button>
        )}

        {/* actions: DOM sibling of the tablist, never a child (§2.3) —
            32px minimum gap enforced by pl-8 alone in both states: with no
            overflow it measures last-tab→actions directly; with overflow
            the scroll-right arrow (32px) sits before it, so the effective
            last-visible-tab→actions distance is 32px (arrow) + 32px (this
            gap) = 64px, never less than the 32px floor. */}
        {actions != null && actions !== false && (
          <div className="flex items-center gap-2 shrink-0 pl-8">{actions}</div>
        )}
      </div>
    );
  },
);
TabsList.displayName = TabsPrimitive.List.displayName;

// ── TabsTrigger ───────────────────────────────────────────────────────────────

/**
 * Semantic color variants for TabsTrigger.badge. Purely decorative — never
 * implies interactivity or clickability (see TabsTriggerProps.badge).
 */
export type TabsTriggerBadgeColor = "brand" | "error";

// Typed with the exact union (not Record<string, string>) so a typo or a
// missing variant fails at compile time instead of silently falling back —
// process/CODE-REVIEW-LEARNINGS.md, PR#13 rule.
const badgeColorClassName: Record<TabsTriggerBadgeColor, string> = {
  brand: "bg-filigran-brand-primary-transparency",
  error: "bg-alert-error",
};

export interface TabsTriggerProps extends React.ComponentPropsWithoutRef<
  typeof TabsPrimitive.Trigger
> {
  /** Optional leading icon — pass a 16×16 icon (rendered inside a 16×16 container) */
  icon?: React.ReactNode;
  /** Optional badge count displayed next to the label */
  badge?: number | string;
  /**
   * Semantic color variant for the badge. Purely decorative — does not imply
   * interactivity or clickability; the badge never renders a click handler
   * regardless of color. Default: "brand" (existing tinted brand color,
   * unchanged). Ignored when asChild is true or badge is undefined.
   */
  badgeColor?: TabsTriggerBadgeColor;
  /**
   * Caps a numeric badge: when `badge` is a number greater than `badgeMax`,
   * renders `${badgeMax}+` instead of the raw value (e.g. badge={150}
   * badgeMax={99} → "99+"). Ignored for string badges and uncapped by
   * default (no default value) — non-breaking for any existing numeric
   * badge usage. A negative or non-finite `badgeMax` (e.g. -1, NaN,
   * Infinity) is treated as uncapped rather than applied literally, so it
   * can never render a nonsensical value like "-1+". Ignored when asChild
   * is true.
   */
  badgeMax?: number;
  /**
   * Hides the badge without any other change to the trigger — equivalent to
   * omitting `badge`. Provided as an explicit prop for ergonomic conditional
   * usage (e.g. badgeInvisible={count === 0}) and for parity with MUI
   * Badge's `invisible` prop. The badge element is not rendered at all when
   * true (no CSS-only hiding, no residual DOM/accessibility-tree node).
   * Ignored when asChild is true.
   */
  badgeInvisible?: boolean;
  /**
   * Merge trigger props onto a single child element instead of rendering a
   * <button>. Use with React Router <Link> for route-based tabs:
   *   <TabsTrigger value="overview" asChild>
   *     <Link to="/overview">Overview</Link>
   *   </TabsTrigger>
   * When asChild is true, icon and badge props (including badgeColor,
   * badgeMax, badgeInvisible) are ignored — compose them inside the child
   * element manually if needed. This is also the supported way to build a
   * clickable badge/chip (e.g. OpenCTI's EEChip pattern): TabsTrigger's own
   * badge stays purely decorative and is never clickable.
   */
  asChild?: boolean;
}

const TabsTrigger = React.forwardRef<
  React.ElementRef<typeof TabsPrimitive.Trigger>,
  TabsTriggerProps
>(
  (
    {
      className,
      icon,
      badge,
      badgeColor = "brand",
      badgeMax,
      badgeInvisible = false,
      children,
      asChild = false,
      ...props
    },
    ref,
  ) => {
    const showBadge = badge !== undefined && !badgeInvisible;
    // Cap applies only to numeric badges (parity with MUI Badge.max, which
    // likewise never caps a string badgeContent). A negative or non-finite
    // badgeMax is treated as uncapped (ignored) rather than applied
    // literally — otherwise e.g. badgeMax={-1} would render "-1+"
    // (PR#56 review finding).
    const hasValidCap = badgeMax !== undefined && Number.isFinite(badgeMax) && badgeMax >= 0;
    const displayBadge =
      typeof badge === "number" && hasValidCap && badge > badgeMax ? `${badgeMax}+` : badge;

    return (
      <TabsPrimitive.Trigger
        ref={ref}
        asChild={asChild}
        className={cn(
          // Base layout — matches Figma: row, px-4, gap-2, h-11
          "group inline-flex items-center justify-center gap-2",
          "h-11 px-4",
          "rounded-t-sm",
          "transition",
          // Default text: body-base / secondary colour
          "font-content-base text-content-base leading-content-base tracking-content-base",
          "text-default-secondary",
          // Hover (default state)
          "hover:bg-filigran-brand-primary-transparency",
          // Reserve 2px border space in base to prevent height shift when tab activates.
          // Border width matches TabsList so the active indicator overlays the list border.
          "border-b-2 border-transparent",
          // Active state (selected tab) — bottom indicator + bold text + brand colour
          // font-semibold: font-content-button alone only ever resolved font-
          // family (see Text.tsx's file-level comment) — it never actually made
          // the label bold/semibold as this comment always intended. Fixed
          // 2026-07-23 (PR #44 review finding), same gap as Button.tsx.
          "data-[state=active]:font-content-button",
          "data-[state=active]:font-semibold",
          "data-[state=active]:text-filigran-brand-primary",
          "data-[state=active]:border-filigran-brand-primary",
          // Disabled state — both :disabled (native button) and data-[disabled] (Radix asChild mode)
          "disabled:pointer-events-none disabled:text-default-disabled",
          "data-[disabled]:pointer-events-none data-[disabled]:text-default-disabled",
          // Focus ring — standard pattern
          "focus-visible:outline-none focus-visible:ring-2 ring-focus",
          "focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
          className,
        )}
        {...props}
      >
        {asChild ? (
          // Single child required for Slot — icon/badge (and its color/max/
          // invisible variants) are not supported in asChild mode
          children
        ) : (
          <>
            {/* Decorative icon */}
            {icon && (
              <span className="flex-none w-4 h-4" aria-hidden="true">
                {icon}
              </span>
            )}

            {/* Label */}
            {children}

            {/* Badge / count — purely decorative, never clickable. A
                consumer needing a clickable badge/chip (e.g. OpenCTI's
                EEChip) must compose it via TabsTrigger asChild instead. */}
            {showBadge && (
              <span
                className={cn(
                  "inline-flex items-center justify-center",
                  "px-1 rounded-sm",
                  "font-content-caption text-content-caption leading-content-caption tracking-content-caption",
                  "text-default-primary",
                  badgeColorClassName[badgeColor],
                  "group-data-[disabled]:bg-elevation-disabled group-data-[disabled]:text-default-disabled",
                )}
                aria-label={`${displayBadge} items`}
              >
                {displayBadge}
              </span>
            )}
          </>
        )}
      </TabsPrimitive.Trigger>
    );
  },
);
TabsTrigger.displayName = TabsPrimitive.Trigger.displayName;

// ── TabsContent ───────────────────────────────────────────────────────────────

const TabsContent = React.forwardRef<
  React.ElementRef<typeof TabsPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof TabsPrimitive.Content>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Content
    ref={ref}
    className={cn(
      "focus-visible:outline-none focus-visible:ring-2 ring-focus",
      "focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
      className,
    )}
    {...props}
  />
));
TabsContent.displayName = TabsPrimitive.Content.displayName;

export { Tabs, TabsList, TabsTrigger, TabsContent };
