import * as React from "react";
import * as DropdownMenuPrimitive from "@radix-ui/react-dropdown-menu";

import { cn } from "../../lib/cn";
import { useNavbarCollapsed } from "../navbar/NavbarContext";
import { Icon } from "../icon";
import { IconButton } from "../icon-button";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "../tooltip";

// No dedicated Figma symbol exists for this component (ProductSwitcher.rfc.md
// §3.1/§3.6) — anatomy is sourced from opencti's real, live-wired
// `LeftBarHeader`/`PopoverListItem` instead. ⚠️ Every color token below is
// REUSED from NavbarItem/NavbarSubmenuItem (RFC §3.4): @sandy confirmed the
// only visual references available for this component (the Figma productLogo
// header + the reference screenshot) show structure/behavior only, not real
// colors — flagged "to revalidate" rather than treated as final. Radius
// removed in the fidelity re-pass (2026-07-23): no Figma node covers this row
// directly, but the confirmed zero-radius finding on NavbarItem/
// NavbarSubmenuItem's own rows (node 6291:4003) is extrapolated here for
// internal consistency, per @sandy's standing instruction to reuse this
// batch's confirmed values in the absence of a reliable source for this
// component specifically — flagged, not an independent Figma confirmation.
const productSwitcherItemClass = cn(
  "flex w-full items-center gap-2 h-9 px-2",
  // Typography: fidelity re-pass #2 point 7 — this row had NO font-size/
  // weight/line-height/tracking classes at all (a real gap, not a
  // reuse-elsewhere choice); applying NavbarItem's confirmed content-base
  // treatment (node 6291:4003 lineage) for internal batch consistency, per
  // @sandy's standing instruction to reuse this batch's confirmed values in
  // the absence of a reliable Figma source for this component specifically.
  "font-content-base text-content-base leading-normal tracking-content-base",
  // text-default-primary doubles as the external-link icon's color (SVG
  // `currentColor` inheritance) — `--icon-default` (RFC §3.4) resolves to
  // this exact same token in theme.css, so no separate icon-color class
  // is needed on the icon span itself.
  "text-default-primary",
  "hover:bg-elevation-highlight", // ⚠️ reused from NavbarItem §3.4, to revalidate
  "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
);

export interface ProductSwitcherOption {
  id: string;
  /**
   * Accessible name for this link. Never rendered as visible text — `logo`
   * is the item's sole visible content (RFC §3.2/§4.1). Used verbatim as the
   * link's accessible name, and as the base for the visually-hidden
   * "(opens in a new tab)" suffix when `href` is set (RFC §5.3).
   */
  label: string;
  /** Product wordmark/logo — the item's sole visible content. Rendered
   * `aria-hidden` (the accessible name comes from `label`, not from
   * whatever alt text a consumer's logo asset may or may not carry). */
  logo: React.ReactNode;
  /** Optional supplementary tooltip (e.g. connection status). Copy is the
   * consuming product's responsibility (RFC §4.1/§6.3) — not populated here. */
  tooltip?: string;
  /**
   * External destination. Renders `target="_blank"` + `rel="noopener
   * noreferrer"`, a visible "opens in a new tab" icon (`aria-hidden`), and
   * appends the AT-only "(opens in a new tab)" suffix to the accessible
   * name — corrects a real WCAG gap in opencti's current icon-only
   * implementation (RFC §2.3/§2.4/§5.3). Mutually exclusive with `to`: if
   * both are set, `href` takes priority and `to` is silently ignored at
   * runtime, but a dev-only `console.warn` fires to flag the contract
   * violation (see `AGENTS.md` "Prop contract violations", never thrown,
   * silent in production).
   */
  href?: string;
  /**
   * Internal destination. Mutually exclusive with `href` — see `href`'s doc
   * for the effective priority and dev-warning behavior when both are set.
   * Real precedent: opencti's XTM Hub entry links internally to a
   * connection/settings page when not yet connected (RFC §2.3). Rendered as
   * a same-tab `<a href>` — the design system has no dependency on any
   * specific router, so true zero-reload client-side navigation depends on
   * the consuming app's router intercepting anchor clicks (documented gap,
   * not a silent guess — see Final Summary).
   */
  to?: string;
}

export interface ProductSwitcherProps extends React.ComponentPropsWithoutRef<"button"> {
  /** Current product's logo, always-visible trigger content in both
   * `Navbar` collapse states (RFC §3.6) — the trigger itself never becomes
   * non-interactive. Rendered `aria-hidden`; `label` carries the a11y name. */
  logo: React.ReactNode;
  /** Accessible name for the trigger button. Not rendered as visible text
   * (RFC §4.1) — deliberately distinct from "Collapse"/"Expand" so it never
   * clashes with `Navbar`'s own, unrelated collapse toggle (RFC §5.3). */
  label: string;
  /** Other Filigran products/destinations. */
  options: ProductSwitcherOption[];
}

/**
 * The `ProductSwitcherOption` renderer: picks the correct interactive
 * element per RFC §2.3's confirmed real per-item polymorphism (external
 * anchor / internal anchor / inert fallback when neither destination is
 * given, matching opencti's own real `<div>` fallback case) and wraps it in
 * the shared `Tooltip` only when the option actually carries one.
 */
function ProductSwitcherOptionItem({ option }: { option: ProductSwitcherOption }) {
  const external = Boolean(option.href);

  // Prop-contract violation (`href`/`to` are documented mutually exclusive,
  // see the ProductSwitcherOption doc above) — dev-only diagnostic per
  // AGENTS.md "Prop contract violations": warn, never throw, `href` still
  // wins so behavior stays deterministic. `typeof process !== "undefined"`:
  // same guard as ProductSwitcher.meta.ts's basePath resolution — this is a
  // package file, not docs/, so it can be consumed by a bare bundler/runtime
  // with no `process` global at all, where the bare reference would throw
  // (review comment, PR #43 round 3) rather than just failing to
  // dead-code-eliminate.
  if (
    typeof process !== "undefined" &&
    process.env.NODE_ENV !== "production" &&
    option.href &&
    option.to
  ) {
    console.warn(
      `ProductSwitcher: option "${option.id}" sets both \`href\` and \`to\`, which are documented as mutually exclusive. \`href\` takes priority and \`to\` is ignored.`,
    );
  }

  const body = (
    <>
      <span className="inline-flex shrink-0 items-center" aria-hidden="true">
        {option.logo}
      </span>
      <span className="sr-only">
        {option.label}
        {external && " (opens in a new tab)"}
      </span>
      {external && (
        <span className="ml-auto inline-flex shrink-0" aria-hidden="true">
          <Icon name="external-link" size={16} />
        </span>
      )}
    </>
  );

  let element: React.ReactElement;
  const inert = !option.href && !option.to;
  if (option.href) {
    element = (
      <a
        href={option.href}
        target="_blank"
        rel="noopener noreferrer"
        className={productSwitcherItemClass}
      >
        {body}
      </a>
    );
  } else if (option.to) {
    element = (
      <a href={option.to} className={productSwitcherItemClass}>
        {body}
      </a>
    );
  } else {
    // No destination given — inert row, mirrors opencti's real `<div>`
    // fallback (RFC §2.3) rather than silently rendering a broken link.
    element = (
      <div className={cn(productSwitcherItemClass, "cursor-default opacity-60")}>{body}</div>
    );
  }

  // Radix's own `disabled` (not just visual styling) so the inert row is
  // skipped by arrow-key roving focus and never fires onSelect — a plain
  // `role="menuitem"` with no destination would otherwise still be a
  // keyboard-reachable dead end (not addressed explicitly by RFC §5.1, a
  // necessary refinement of it).
  const item = (
    <DropdownMenuPrimitive.Item asChild disabled={inert}>
      {element}
    </DropdownMenuPrimitive.Item>
  );

  if (!option.tooltip) {
    return item;
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>{item}</TooltipTrigger>
      <TooltipContent side="left">{option.tooltip}</TooltipContent>
    </Tooltip>
  );
}

/**
 * The `Navbar` header control exposing links to sibling Filigran products —
 * a static menu of destination links (most external, at least one
 * conditionally internal per real opencti usage), never a stateful
 * "current product" selector (no selected/active option, RFC §1/§2.3). Built
 * on `@radix-ui/react-dropdown-menu` since this is an actions/links menu, not
 * a form control — default `modal` behavior is kept (unlike `NavbarSubmenu`,
 * this trigger opens only on click/keyboard, never on hover, so there is no
 * hover/click race to guard against, RFC §5.2).
 */
export const ProductSwitcher = React.forwardRef<HTMLButtonElement, ProductSwitcherProps>(
  ({ className, logo, label, options, ...props }, ref) => {
    const collapsed = useNavbarCollapsed();

    // Fidelity re-pass #4 point 4 (Figma node 6332:10103, file
    // 0PmhuZzF9XcaIEfMMW2a51): the real "productLogo" row is TWO separate
    // elements — a 129x28 logo and a distinct 24x24 rounded-[4px] IconButton
    // housing the chevron ("arrow_drop_down") — not one large clickable
    // surface. `h-7` (28px) matches the logo slot's own measured height;
    // `overflow-hidden` mirrors that node's `overflow-clip` so an
    // oversized/odd-aspect consumer logo clips instead of breaking the
    // row's height, exactly as Figma models it.
    const logoSpan = (
      <span className="inline-flex h-7 shrink-0 items-center overflow-hidden" aria-hidden="true">
        {logo}
      </span>
    );

    const menu = (
      <DropdownMenuPrimitive.Portal>
        <DropdownMenuPrimitive.Content
          side="bottom"
          align="end"
          sideOffset={8}
          className={cn(
            // Fidelity re-pass #2 point 1: no dedicated Figma frame exists
            // for this menu (RFC §3.1/§3.6), but the confirmed real
            // NavbarSubmenu flyout (node 6301:10728) has no
            // border/shadow/radius/padding — reused here for the same
            // reason as the color tokens above (@sandy's standing "reuse
            // this batch's confirmed values" instruction). `min-w-48`
            // unchanged: no source (Figma or otherwise) suggests a
            // different width for this specific menu.
            "z-50 min-w-48",
            "bg-elevation-default",
            // Same fade pattern as Tooltip.tsx / NavbarSubmenu.tsx, extended
            // with motion-reduce awareness per this batch's shared §3.5 decision.
            "opacity-0 transition-opacity duration-150 motion-reduce:transition-none",
            "data-[state=open]:opacity-100 data-[state=closed]:opacity-0",
          )}
        >
          {/* One shared Provider for the whole list — unlike NavbarItem's
              deliberate per-instance Provider (standalone-usage trade-off),
              every option here is rendered together by the same parent, so
              a single shared hover-delay group is the natural choice. */}
          <TooltipProvider>
            {options.map((option) => (
              <ProductSwitcherOptionItem key={option.id} option={option} />
            ))}
          </TooltipProvider>
        </DropdownMenuPrimitive.Content>
      </DropdownMenuPrimitive.Portal>
    );

    // Collapsed: Figma's own collapsed symbol has no separate chevron
    // button at all (RFC §3.6, confirmed again against node 6332:10103 —
    // only the expanded frame shows the IconButton) — the logo itself stays
    // the sole focusable/interactive Trigger, centered across the 48px rail
    // exactly like Navbar's header logo and NavbarItem's collapsed icon
    // (re-pass #4 point 2's `justify-center px-0` pattern).
    if (collapsed) {
      return (
        <DropdownMenuPrimitive.Root>
          <DropdownMenuPrimitive.Trigger
            ref={ref}
            className={cn(
              "inline-flex h-9 w-full items-center justify-center px-0",
              "text-default-primary",
              "hover:bg-elevation-highlight", // ⚠️ reused from NavbarItem §3.4, to revalidate
              "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
              className,
            )}
            {...props}
            // Placed after the spread: `label` is the required, single
            // source of truth for this trigger's accessible name (doc
            // comment on the prop) — a caller-supplied `aria-label` in
            // `...props` (a valid native button attribute, not excluded
            // from ProductSwitcherProps) must never silently win over it
            // and desync the announced name from the actually-rendered
            // (aria-hidden) logo/menu content.
            aria-label={label}
          >
            {logoSpan}
          </DropdownMenuPrimitive.Trigger>
          {menu}
        </DropdownMenuPrimitive.Root>
      );
    }

    // Expanded: matches Figma's row exactly — `h-9` (36px), `justify-between`
    // putting the logo flush-left and the IconButton flush-right. No pl-/pr-
    // of its own: Navbar's header wrapper (Navbar.tsx, node 2843:5134)
    // already applies `pl-4 pr-1` unconditionally around the whole `header`
    // slot — adding the same padding here too would double it (8px instead
    // of Figma's measured 4px on the right). This differs from NavbarItem,
    // which DOES own its full pl-4/pr-2 itself (its ancestor items-list
    // wrapper applies no horizontal padding at all) — two different slots,
    // two different established patterns, not a shared one. The real
    // `IconButton` (`size="sm"` = 24x24 + always `rounded-sm`) is now the
    // actual Radix Trigger — previously an ad-hoc button wrapped both logo
    // and chevron together, which didn't match Figma's two-element structure
    // and wasn't the library's real IconButton as ProductSwitcher.rfc.md's
    // own crosswalk (§2.1) already specified.
    return (
      <DropdownMenuPrimitive.Root>
        <div className="flex h-9 w-full items-center justify-between">
          {logoSpan}
          <DropdownMenuPrimitive.Trigger asChild>
            <IconButton
              ref={ref}
              icon={
                <span className="transition-transform duration-150 motion-reduce:transition-none group-data-[state=open]:rotate-180">
                  <Icon name="chevron-down" size={16} />
                </span>
              }
              size="sm"
              priority="tertiary"
              className={cn(
                "group",
                // Overrides tertiary's default brand-blue treatment to match
                // the rest of this batch's confirmed neutral tokens
                // (NavbarItem/NavbarSubmenuItem, ProductSwitcher.rfc.md §3.4)
                // — no reliable Figma color source exists for this component.
                "text-default-primary hover:bg-elevation-highlight active:bg-elevation-highlight",
                "focus-visible:ring-focus",
                className,
              )}
              {...props}
              // See the collapsed-trigger above: placed after the spread so
              // the required `label` prop always wins over a stray
              // caller-supplied `aria-label`.
              aria-label={label}
            />
          </DropdownMenuPrimitive.Trigger>
        </div>
        {menu}
      </DropdownMenuPrimitive.Root>
    );
  },
);

ProductSwitcher.displayName = "ProductSwitcher";
