import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../../lib/cn";

// Every class below is a native, token-backed Tailwind utility resolved from
// theme.css's per-Named-Style CSS custom properties (see Text.figma.json and
// Text.rfc.md §3.3) — never a hardcoded value; pnpm check:tokens enforces
// this. Decomposed per-variant form (font-/text-/leading-/tracking-, plus a
// weight utility on non-regular variants — see below), matching the
// established convention in Tabs.tsx / Tooltip.tsx / Button.tsx. theme.css
// also defines a single bundling `@utility <name>` class per Named Style
// ("Typography Style Utilities" section, e.g. `@utility content-base`) but
// no shipped component consumes that composite form today — Text follows
// the decomposed precedent for consistency with the rest of the library
// rather than introducing a second convention.
//
// Font-weight fix (2026-07-23, PR #44 review finding): `font-<name>` only
// ever resolves theme.css's `--font-<name>` custom property, i.e.
// font-family — it does NOT also apply the sibling `--font-weight-<name>`
// property the way the composite `@utility <name>` blocks do. Confirmed
// empirically against the compiled CSS: `.font-content-base-bold` (etc.)
// generates a single `font-family` declaration only. This silently starved
// every non-regular Named Style (15 of Text's 19 variants) of its intended
// weight, defaulting to the browser/inherited 400 — same pre-existing gap
// in Button.tsx (`content-button`, unconditional) and Tabs.tsx (active-tab
// state), both fixed alongside this component in the same PR. Regular-
// weight variants (content-base, content-compact, content-caption,
// content-code) and Tooltip.tsx (content-compact only) were audited and
// need no change: the absence of an explicit weight class already
// coincides with the intended 400. Fixed here by adding Tailwind's own
// native keyword utility (font-medium/font-semibold/font-bold — these are
// NOT theme-scale lookups, they map directly to `--font-weight-medium:
// 500` / `--font-weight-semibold: 600` / `--font-weight-bold: 700`,
// declared in theme.css and confirmed to compile correctly) next to each
// non-regular variant's existing 4 classes. theme.css itself is untouched.
const textVariants = cva("", {
  variants: {
    variant: {
      "title-2xl": "font-title-2xl font-medium text-title-2xl leading-title-2xl tracking-title-2xl",
      "title-xl": "font-title-xl font-medium text-title-xl leading-title-xl tracking-title-xl",
      "title-lg": "font-title-lg font-medium text-title-lg leading-title-lg tracking-title-lg",
      "title-md": "font-title-md font-medium text-title-md leading-title-md tracking-title-md",
      "title-sm": "font-title-sm font-bold text-title-sm leading-title-sm tracking-title-sm",
      "title-xs": "font-title-xs font-semibold text-title-xs leading-title-xs tracking-title-xs",
      "title-jumbo":
        "font-title-jumbo font-medium text-title-jumbo leading-title-jumbo tracking-title-jumbo",
      "content-base":
        "font-content-base text-content-base leading-content-base tracking-content-base",
      "content-base-bold":
        "font-content-base-bold font-semibold text-content-base-bold leading-content-base-bold tracking-content-base-bold",
      "content-base-medium":
        "font-content-base-medium font-medium text-content-base-medium leading-content-base-medium tracking-content-base-medium",
      // The two -link variants render <a> by default (TEXT_DEFAULT_TAG) and
      // are the only case where Text's own default element is genuinely
      // interactive/focusable (a real <a href>) — see RFC §5.4/§6.3. The
      // standard focus-ring pattern (AGENTS.md "Interactive Elements") is
      // included here; it is inert via :focus-visible when the consumer
      // renders a non-navigable, href-less anchor (RFC §4.1 link-variant
      // note) or overrides `as` to a non-focusable element.
      "content-base-link":
        "font-content-base-link font-medium text-content-base-link leading-content-base-link tracking-content-base-link underline focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
      "content-compact":
        "font-content-compact text-content-compact leading-content-compact tracking-content-compact",
      "content-compact-bold":
        "font-content-compact-bold font-semibold text-content-compact-bold leading-content-compact-bold tracking-content-compact-bold",
      "content-compact-medium":
        "font-content-compact-medium font-medium text-content-compact-medium leading-content-compact-medium tracking-content-compact-medium",
      "content-compact-link":
        "font-content-compact-link font-medium text-content-compact-link leading-content-compact-link tracking-content-compact-link underline focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
      "content-caption":
        "font-content-caption text-content-caption leading-content-caption tracking-content-caption",
      "content-highlight":
        "font-content-highlight font-semibold text-content-highlight leading-content-highlight tracking-content-highlight",
      "content-button":
        "font-content-button font-semibold text-content-button leading-content-button tracking-content-button",
      "content-code":
        "font-content-code text-content-code leading-content-code tracking-content-code",
    },
  },
});

export type TextVariant = NonNullable<VariantProps<typeof textVariants>["variant"]>;

/**
 * Native HTML element rendered by default when `as` is omitted, per variant.
 * Deliberately NOT derived from `variant` at runtime — `as` and `variant`
 * never merge (RFC "already-settled arbitration"). Full per-row rationale:
 * Text.rfc.md §4.1.
 */
export const TEXT_DEFAULT_TAG = {
  "title-2xl": "h1",
  "title-xl": "h2",
  "title-lg": "h3",
  "title-md": "h4",
  "title-sm": "h5",
  "title-xs": "h6",
  "title-jumbo": "p",
  "content-base": "p",
  "content-base-bold": "p",
  "content-base-medium": "p",
  "content-base-link": "a",
  "content-compact": "p",
  "content-compact-bold": "p",
  "content-compact-medium": "p",
  "content-compact-link": "a",
  "content-caption": "span",
  "content-highlight": "p",
  "content-button": "span",
  "content-code": "code",
} as const satisfies Record<TextVariant, React.ElementType>;

type PolymorphicRef<C extends React.ElementType> = React.ComponentPropsWithRef<C>["ref"];

interface TextOwnProps<C extends React.ElementType = React.ElementType> {
  /**
   * The semantic element to render — never affects the visual style, which
   * comes exclusively from `variant`. Defaults to a sensible native tag per
   * `variant` when omitted (see TEXT_DEFAULT_TAG).
   *
   * Accepts an intrinsic tag (`"h1"`, `"span"`, ...) or a custom component
   * (`React.ElementType`, settled RFC §4.2/§4.3 — real precedent: 5/494
   * openaev usages already hand-roll this via MUI's `component` prop). A
   * custom component supplied here is responsible for forwarding
   * `className` and `ref` onto its own rendered root itself — same
   * requirement Radix's own `asChild`/Slot pattern places on its child.
   * Text does not verify this at compile-time or runtime (2026-07-23 fix,
   * PR #44 review: the prior wording here said "native HTML element",
   * which undersold the real, deliberately-typed scope and could mislead
   * consumers about the forwarding contract).
   */
  as?: C;
  /**
   * The Named Style to apply (theme.css / process/TYPO-MAPPING.md) — the
   * visual choice. Required: no silent default (RFC §2.4/§4.2 — MUI's own
   * implicit `body1` default was found to cause ambiguity in 11% of real
   * usages).
   */
  variant: TextVariant;
  className?: string;
  children: React.ReactNode;
}

export type TextProps<C extends React.ElementType> = TextOwnProps<C> &
  Omit<React.ComponentPropsWithoutRef<C>, keyof TextOwnProps<C>>;

// React.forwardRef's own type signature can't express a generic render
// function (the `C` type parameter would collapse to a single concrete
// instantiation) — this is the standard "as prop" polymorphic pattern:
// write the forwardRef call normally, then cast the result back to a
// generic call signature. No prior precedent in this repo (every other
// component picks one fixed element or uses Radix's asChild/Slot instead —
// RFC §4.3), since Text is the first genuinely polymorphic component.
//
// `C`'s default (2026-07-23 fix, PR #44 review — suppressed comment,
// Text.tsx:123): previously a fixed `"p"`, which didn't match the actual
// runtime default tag for most variants (TEXT_DEFAULT_TAG), most visibly
// breaking `href` passthrough typing on the two `-link` variants when `as`
// is omitted — exactly the ergonomic case the RFC's own default-tag table
// (§4.1) promises works. `V` (the variant literal) is inferred first from
// the required `variant` prop, then `C` defaults to that specific variant's
// real default tag — `(typeof TEXT_DEFAULT_TAG)[V]` — instead of a constant.
// A literal `variant` (the common case) now narrows `C` correctly (e.g.
// `variant="content-base-link"` defaults `C` to `"a"`, so `href` type-checks
// without an explicit `as="a"`); a widened `variant: TextVariant` (e.g. a
// value threaded through a loop or a wrapper prop) still falls back to the
// union of every possible default tag, same as before this fix.
type TextComponent = <
  V extends TextVariant,
  C extends React.ElementType = (typeof TEXT_DEFAULT_TAG)[V],
>(
  props: TextProps<C> & { variant: V; ref?: PolymorphicRef<C> },
) => React.ReactElement | null;

// forwardRef itself is given a single concrete (non-generic) signature —
// it cannot type-check a generic render function directly — and the
// exported binding is cast to the real polymorphic TextComponent signature
// afterward, which is what callers actually see and get type-checked
// against.
const TextRenderFn = React.forwardRef<Element, TextProps<React.ElementType>>(
  ({ as, variant, className, children, ...props }, ref) => {
    const Component = (as ?? TEXT_DEFAULT_TAG[variant as TextVariant]) as React.ElementType;
    return (
      <Component ref={ref} className={cn(textVariants({ variant }), className)} {...props}>
        {children}
      </Component>
    );
  },
);

export const Text = TextRenderFn as unknown as TextComponent & {
  displayName?: string;
};

Text.displayName = "Text";
