import * as React from "react";
import { Slot } from "@radix-ui/react-slot";

import { cn } from "../../lib/cn";
import { useNavbarCollapsed } from "../navbar/NavbarContext";
import { Icon } from "../icon";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "../tooltip";

// Figma 5125:47152 ("navbar menu item"). Fidelity re-pass (2026-07-23, node
// 6291:4003 — a reachable instance with a real selected/open row) corrected
// three findings from the original extraction: (1) the row itself carries
// NO radius in Figma (only a small header IconButton elsewhere in the frame
// does — `rounded-sm` here was a bug); (2) line-height is 150%
// (`--leading-normal`), not the 115% every `leading-content-*` composite
// hardcodes; (3) the real "selected" row (open + active "Analyses") uses a
// 2px left border (Tailwind's static border-width scale, not spacing-scale-
// derived), not 3px, and keeps the label at `--text-default-primary` rather
// than switching to brand blue —
// correcting the openaev-TenantSwitcher-sourced proposal this used before
// any Figma evidence existed for this state. hover/focus/disabled remain
// precedent-based proposals, flagged ⚠️ in NavbarItem.rfc.md §3.4/§3.6
// pending design confirmation. `group` enables the chevron's rotation below
// to react to an ancestor Radix primitive's `data-state` (see the chevron
// span).
// Reserved indicator border (the aria-current="page" left accent) is a
// real, always-present 2px left border — transparent when unselected,
// brand-colored when selected (`aria-[current=page]:border-l-*` below) —
// so selecting a route never shifts layout: the border's WIDTH never
// changes, only its color. In collapsed mode this one-sided border shifts
// a `justify-center` row's midpoint off the header logo's centerline by
// half its own width; the icon span's `mr-0.5` below counterbalances it
// (full rationale on that span). Both values are Tailwind's own
// permanently-fixed core utilities — the border-width scale's `2` step
// (2px) and the spacing scale's `0.5` step (2px, at this project's
// unmodified default `--spacing: 0.25rem`) — not arbitrary or interpolated
// numbers, so there is no runtime constant needed to keep them in sync:
// both are static, literal Tailwind classes, visible to the Oxide/JIT
// scanner exactly like any other utility. `docs/components/DocsNavbar.tsx`'s
// TopNavLink mirrors the same two classes for its own composed icon.

function navbarItemClass(collapsed: boolean) {
  return cn(
    "group relative flex w-full items-center gap-2 h-9 pl-4 pr-2",
    "transition-colors",
    "font-content-base text-content-base leading-normal tracking-content-base",
    "text-default-primary",
    // Real 2px left border, always present in every state (color-only
    // toggle below, never width) — transparent by default (Figma-confirmed
    // width, node 6291:4003 — was 3px pre-fidelity-re-pass).
    "border-l-2 border-l-transparent",
    "hover:bg-elevation-highlight", // ⚠️ proposed, see RFC §3.4
    "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
    "disabled:pointer-events-none disabled:text-default-disabled data-[disabled]:pointer-events-none data-[disabled]:text-default-disabled",
    // "Selected" is derived from aria-current="page" — no separate prop (RFC
    // §4.2). Text color intentionally does NOT change (Figma-confirmed, node
    // 6291:4003): only bg + border carry the brand accent.
    "aria-[current=page]:bg-filigran-brand-primary-transparency aria-[current=page]:border-l-filigran-brand-primary",
    // Fidelity re-pass #4 point 2 / re-pass #5: collapsed rows were
    // left-anchored (pl-4 pr-2, same as expanded) and relied on the icon
    // happening to be exactly 16px wide for pl-4(16px) to coincidentally
    // land its center at the row's true midpoint. That coincidence broke
    // once the reserved left border was accounted for: `justify-center`
    // centers content within the box MINUS the one-sided border, so its
    // available midpoint sits exactly half the border's own width to the
    // right of the row's true visual center — confirmed empirically
    // (getBoundingClientRect: icon centerX 25.00 vs header logo centerX
    // 24.00 in a 48px row, delta collapses to exactly 0.00 the instant the
    // border is neutralized — no second cause). The icon span's own
    // `mr-0.5` counterbalances this precisely; row layout itself needs no
    // further change beyond mirroring the header row's `justify-center
    // px-0` collapsed treatment (Navbar.tsx).
    collapsed && "justify-center px-0",
  );
}

export interface NavbarItemProps extends React.ComponentPropsWithoutRef<"button"> {
  /**
   * Radix asChild — merges NavbarItem styles onto the child element
   * (typically a router `Link`), same pattern as `Button`. `icon`/`showIcon`/
   * `chevron` are ignored in this mode — Slot cannot inject wrapper elements
   * around/inside an arbitrary child, so compose them into your own child
   * if you need them alongside a custom link.
   */
  asChild?: boolean;
  /**
   * Leading icon. Hidden entirely (no fallback/initials) when `showIcon` is
   * `false` — the label then takes the full row width, no layout shift.
   */
  icon?: React.ReactNode;
  /**
   * Whether the leading icon renders. Default `true`. Mirrors opencti's real
   * `submenu_show_icons` preference (RFC §2.3). Forced to effectively `true`
   * while the ancestor Navbar is collapsed, so the row is never rendered
   * fully content-less (RFC §3.6).
   */
  showIcon?: boolean;
  /**
   * Shows the trailing submenu-indicator chevron, fully independent of
   * `icon`/`showIcon` (Figma-confirmed, RFC §3.2). Set by `NavbarSubmenu`
   * when composing `NavbarItem` as its trigger row — rarely set directly.
   * Rotates automatically via `data-state` if an ancestor Radix trigger
   * (e.g. Accordion.Trigger) merges it onto this row through `asChild`.
   */
  chevron?: boolean;
  /** Row label. */
  children: React.ReactNode;
  /**
   * Accessible label duplicated into the collapsed-mode Tooltip's content
   * (§5.3). Only needed with `asChild`: in that mode `children` is the
   * slotted element itself (e.g. a `<Link>` composing its own icon/label
   * spans), not plain label text, so reusing it verbatim inside
   * `TooltipContent` would nest a focusable element inside the tooltip
   * bubble — invalid per the WAI-ARIA tooltip pattern (non-interactive
   * content only) as well as visually broken. Ignored when `asChild` is
   * `false`, where `children` already is the plain label and needs no
   * duplicate.
   *
   * Prop-contract violation if omitted while `asChild` is set on a
   * collapsed, non-`chevron` row (review comment, PR #43): rather than
   * mounting an empty tooltip bubble, the Tooltip is skipped entirely and a
   * dev-only `console.warn` fires (never throws) — same precedent as
   * `ProductSwitcher`'s `href`/`to` (AGENTS.md "Prop contract violations").
   */
  tooltipLabel?: React.ReactNode;
}

/**
 * The single interactive row used throughout `Navbar`: a plain navigation
 * link (leaf item), a `NavbarSubmenu` trigger row, and the `Navbar` footer's
 * built-in collapse toggle all render this same component — only icon,
 * chevron, and label content differ per usage.
 *
 * "Selected" styling is derived from the native `aria-current="page"`
 * attribute rather than a redundant boolean prop (NavbarItem.rfc.md §4.2).
 * While the ancestor `Navbar` is collapsed, the row hides its label (kept in
 * the DOM as visually-hidden text, so the accessible name never depends on
 * it disappearing) and wraps itself in the library's `Tooltip`.
 */
export const NavbarItem = React.forwardRef<HTMLButtonElement, NavbarItemProps>(
  (
    {
      className,
      asChild = false,
      icon,
      showIcon = true,
      chevron = false,
      children,
      tooltipLabel,
      disabled,
      type = "button",
      ...props
    },
    ref,
  ) => {
    const collapsed = useNavbarCollapsed();
    const effectiveShowIcon = collapsed || showIcon;

    const row = asChild ? (
      <Slot
        ref={ref}
        className={cn(navbarItemClass(collapsed), className)}
        data-disabled={disabled ? "" : undefined}
        aria-disabled={disabled ? true : undefined}
        {...props}
        {...(disabled
          ? {
              onClick: (e: React.MouseEvent) => e.preventDefault(),
              onKeyDown: (e: React.KeyboardEvent) => {
                if (e.key === "Enter" || e.key === " ") e.preventDefault();
              },
            }
          : {})}
      >
        {children}
      </Slot>
    ) : (
      <button
        ref={ref}
        type={type}
        className={cn(navbarItemClass(collapsed), className)}
        disabled={disabled}
        data-disabled={disabled ? "" : undefined}
        {...props}
      >
        {effectiveShowIcon && icon && (
          // text-default-secondary: fidelity re-pass #2 point 7 — pixel-
          // sampled the live render against Figma node 5425:11518 and found
          // the leading/content icon is #afb0b6 (--gray-300, secondary),
          // while the label and chevron are #f2f2f3 (--gray-100, primary).
          // Content icons and affordance/control icons (chevron) are NOT
          // the same tone in this design — only this span needs overriding;
          // the row's own text-default-primary (label/chevron) is correct.
          //
          // group-data-[disabled]:text-default-disabled: fidelity re-pass
          // #4 point 3 — the icon kept text-default-secondary even when the
          // row was disabled, since that class always wins over the row's
          // own `disabled:text-default-disabled` (which only colors the
          // row/label, and doesn't cascade past this span's own explicit
          // override). Icon.tsx renders every glyph with currentColor by
          // design ("style it with text-* token classes ... never hardcoded
          // values") — Button/IconButton already establish the precedent of
          // `disabled:text-default-disabled` for exactly this, rather than
          // the unused `--icon-disabled` token (theme.css), which is only
          // ever an alias of this same `--text-default-disabled` value and
          // is not consumed by any component or utility actually wired to
          // currentColor-based icons.
          //
          // mr-0.5 (collapsed only): counterbalances the row's own reserved
          // left border (border-l-2 on navbarItemClass()) so this span's
          // center lands on the header logo's centerline (fidelity re-pass
          // #5) — both are static Tailwind core-scale classes (2px each),
          // see the reserved-indicator note above navbarItemClass(). Only
          // needed while collapsed: in expanded rows nothing is centered
          // (`justify-start`/default flow), so the one-sided border has no
          // centering effect to counteract there.
          <span
            className={cn(
              "inline-flex shrink-0 text-default-secondary group-data-[disabled]:text-default-disabled",
              collapsed && "mr-0.5",
            )}
            aria-hidden="true"
          >
            {icon}
          </span>
        )}
        <span className={cn("flex-1 truncate text-left", collapsed && "sr-only")}>{children}</span>
        {chevron && !collapsed && (
          <span
            // 150ms + reduced-motion-aware, matching Navbar.rfc.md §3.5's
            // sidebar-width transition decision for consistency (NavbarSubmenu.rfc.md §3.5).
            // Hidden entirely while collapsed — confirmed real OpenCTI
            // behavior (@sandy, fidelity re-pass instructions), fixed here
            // since the row previously kept rendering it regardless of
            // `collapsed`. The submenu it triggers stays reachable via the
            // collapsed-mode flyout on the row itself; no other visual
            // affordance is needed once the chevron is gone.
            className="inline-flex shrink-0 transition-transform duration-150 motion-reduce:transition-none group-data-[state=open]:rotate-180"
            aria-hidden="true"
          >
            <Icon name="chevron-down" size={16} />
          </span>
        )}
      </button>
    );

    // Icon-only (collapsed) rows need a text alternative: wrap in the
    // library's real Tooltip, duplicating the same label, so the accessible
    // name never silently depends on visually-hidden text alone (RFC §5.3).
    // Radix's Tooltip.Root throws without an ancestor TooltipProvider, so we
    // wrap defensively here rather than requiring every consumer (including
    // Navbar itself, tests, and docs demos) to remember to supply one. This
    // means each collapsed NavbarItem gets its own independent hover-delay
    // timer (no cross-item "skip delay" coordination) — a deliberate,
    // documented trade-off for standalone correctness over that polish.
    //
    // `|| chevron`: fidelity re-pass #2 point 4 — a row with a submenu
    // (chevron=true) opens a flyout on hover/focus in collapsed mode
    // (NavbarSubmenu.tsx); the Tooltip's own hover/focus-triggered popup was
    // rendering on top of that flyout, hiding it. The flyout already
    // supplies the row's accessible name via its trigger content, so the
    // tooltip is redundant (and actively harmful) for exactly this case —
    // skip it whenever the row is a submenu trigger, regardless of collapsed
    // state.
    //
    // asChild: `children` is the slotted element, not plain text —
    // `tooltipLabel` supplies the accessible duplicate instead (see the prop
    // doc comment above). If omitted, `collapsedTooltipContent` is empty and
    // mounting the Tooltip would produce a real, focus-visible bubble with no
    // content (`role="tooltip"`, empty accessible description) — a
    // prop-contract violation (review comment, PR #43): skip the Tooltip
    // entirely in that case and fire a dev-only warning, same precedent as
    // `ProductSwitcher`'s `href`/`to` (AGENTS.md "Prop contract violations").
    // Non-asChild: `children` already is the plain label — unchanged prior
    // behavior, never affected by this guard.
    const collapsedTooltipContent = asChild ? tooltipLabel : children;
    const missingTooltipLabel = collapsed && !chevron && asChild && !collapsedTooltipContent;

    if (
      typeof process !== "undefined" &&
      process.env.NODE_ENV !== "production" &&
      missingTooltipLabel
    ) {
      console.warn(
        "NavbarItem: `asChild` is set on a collapsed row without `tooltipLabel`. " +
          "The row has no accessible tooltip text to show, so no Tooltip is rendered — pass `tooltipLabel` to restore it.",
      );
    }

    if (!collapsed || chevron || missingTooltipLabel) {
      return row;
    }

    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger asChild>{row}</TooltipTrigger>
          <TooltipContent side="right">{collapsedTooltipContent}</TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  },
);

NavbarItem.displayName = "NavbarItem";
