import { createElement as h } from "react";
import type { ComponentProps } from "react";
import type { ComponentMeta } from "../../types/meta";
import { Switch } from "./Switch";

/** Small state-grid cell used by the render() demo below. */
function cell(labelText: string, props: ComponentProps<typeof Switch>) {
  return h(
    "div",
    { className: "flex flex-col items-start gap-2" },
    h(
      "span",
      {
        className:
          "text-content-caption font-content-caption leading-content-caption tracking-content-caption text-default-secondary",
      },
      labelText,
    ),
    h(Switch, props),
  );
}

