import * as React from "react";
import * as AccordionPrimitive from "@radix-ui/react-accordion";
import * as DropdownMenuPrimitive from "@radix-ui/react-dropdown-menu";
import { Slot } from "@radix-ui/react-slot";

import { cn } from "../../lib/cn";
import { useNavbarCollapsed } from "../navbar/NavbarContext";
import { NavbarItem } from "../navbar-item";

// ── NavbarSubmenuItem ─────────────────────────────────────────────────────

export interface NavbarSubmenuItemProps extends React.ComponentPropsWithoutRef<"a"> {
  /** Radix asChild — same router-Link polymorphism as NavbarItem/Button. */
  asChild?: boolean;
  /**
   * Same verified opencti mechanism as NavbarItem (`submenu_show_icons`) —
   * icon omitted with no fallback when false, label unaffected. Submenu
   * labels never hide, regardless of ancestor collapse state (NavbarItem's
   * *own* row is the only one that hides its label when collapsed) —
   * NavbarSubmenuItem.rfc.md §2.3/§4.2. Default: `true`.
   */
  showIcon?: boolean;
  icon?: React.ReactNode;
  children: React.ReactNode;
}

// Fidelity re-pass (2026-07-23): node 6291:4003 is the first independently
// reachable instance of "navbar submenu item" (an open "Analyses" submenu
// with 6 real rows) — the anatomy below replaces the original
// symmetry-with-NavbarItem proposal (NavbarSubmenu.rfc.md §3.6) now that
// real values exist. Confirmed DIFFERENT from NavbarItem in three ways: (1)
// deeper indent, `pl-6 pr-4` (24px/16px) not `pl-4 pr-2`; (2) smaller,
// dimmer text — 12px `--text-2`/`--text-default-secondary`
// (`content-compact`), not 14px/primary; (3) no radius (same zero-radius
// finding as NavbarItem — `rounded-sm` here was a bug). Line-height (150%,
// `--leading-normal`) and the corrected 2px/no-text-color-change selected
// treatment are the same fixes as NavbarItem, for the same reason (RFC
// §3.4/§4.2). Deliberately NOT built on top of NavbarItem: this row never
// hides its label, so sharing a base component would need an extra prop
// just to suppress that one behaviour — two small independent classNames
// are simpler than that shared abstraction.
const navbarSubmenuItemClass = cn(
  "group relative flex w-full items-center gap-2 h-9 pl-6 pr-4",
  "transition-colors",
  "font-content-compact text-content-compact leading-normal tracking-content-compact",
  "text-default-secondary",
  // 2px left border reserved (transparent) in every state, same reasoning
  // as NavbarItem: the aria-current accent below never shifts row content
  // (Figma-confirmed width, node 6291:4003 — was 3px pre-fidelity-re-pass).
  "border-l-2 border-l-transparent",
  "hover:bg-elevation-highlight", // ⚠️ proposed, see RFC §3.4
  "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
  // "Selected" derived from aria-current="page" — same mechanism as
  // NavbarItem (RFC §4.2). Text color intentionally does not change
  // (Figma-confirmed, node 6291:4003, same evidence as NavbarItem). No
  // left-border accent here (unlike NavbarItem): fidelity re-pass #2 point 1
  // — node 5425:11518 shows the selected submenu row with only the tint,
  // no stroke; the border was an unverified symmetry-with-NavbarItem
  // assumption from the original RFC, now corrected against the real frame.
  "aria-[current=page]:bg-filigran-brand-primary-transparency",
);

/**
 * A single row inside a `NavbarSubmenu`. Documented and shipped only as part
 * of `NavbarSubmenu`'s compound API (mirrors the `Tabs`/`TabsTrigger`
 * precedent) — not intended for standalone use (NavbarSubmenu.rfc.md §4.2).
 */
export const NavbarSubmenuItem = React.forwardRef<HTMLAnchorElement, NavbarSubmenuItemProps>(
  ({ className, asChild = false, icon, showIcon = true, children, ...props }, ref) => {
    if (asChild) {
      return (
        <Slot ref={ref} className={cn(navbarSubmenuItemClass, className)} {...props}>
          {children}
        </Slot>
      );
    }

    return (
      <a ref={ref} className={cn(navbarSubmenuItemClass, className)} {...props}>
        {showIcon && icon && (
          <span className="inline-flex shrink-0" aria-hidden="true">
            {icon}
          </span>
        )}
        <span className="flex-1 truncate text-left">{children}</span>
      </a>
    );
  },
);
NavbarSubmenuItem.displayName = "NavbarSubmenuItem";

// ── NavbarSubmenu ─────────────────────────────────────────────────────────

export interface NavbarSubmenuProps {
  /** Accessible name for the trigger row (rendered via NavbarItem). */
  label: React.ReactNode;
  /** Optional leading icon on the trigger row (passed through to NavbarItem). */
  icon?: React.ReactNode;
  /** Controlled open state. Omit for uncontrolled. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /**
   * Destination for the trigger row, applied ONLY while the ancestor Navbar
   * is collapsed (flyout mode) — mirrors openaev's real `MenuItemGroup`
   * pattern (`component={Link} to={item.path}` when collapsed, `onClick`
   * toggle when expanded; confirmed against opencti's own equivalent
   * `handleParentClick`/`handleGoToPage`, `LeftBarItem.tsx`/`LeftBar.jsx`).
   * While collapsed, the trigger becomes a real, directly-navigable link
   * (`asChild`/Slot onto a plain `<a>`, same mechanism as
   * NavbarItem/NavbarSubmenuItem) IN ADDITION to still opening the flyout on
   * hover/focus — clicking or pressing Enter navigates without also
   * toggling the flyout open/closed (§4.3/§5.2). Ignored entirely in
   * expanded mode: the trigger stays a pure accordion toggle there, exactly
   * as before this feature — a submenu *group* heading is not itself a
   * distinct page when there's room to show its children inline (openaev's
   * own onClick-toggles-only expanded behavior). Mutually exclusive with
   * `to`: if both are set, `href` takes priority and `to` is silently
   * ignored at runtime, with a dev-only `console.warn` (never thrown) — same
   * precedent as `ProductSwitcher`'s `href`/`to` (AGENTS.md "Prop contract
   * violations"). Unlike `ProductSwitcher.href` (external, `target="_blank"`),
   * both props here render an identical plain same-tab anchor — no
   * external-link semantics apply to a submenu group, matching openaev's own
   * purely-internal `to={item.path}` usage; `href`/`to` exist as two names
   * for the same behavior so consumers can match whichever their own
   * router's convention prefers (e.g. Next.js `Link href` vs React Router
   * `Link to`).
   */
  href?: string;
  /**
   * Alias for `href` — see its doc for full behavior, priority, and the
   * dev-warning when both are set.
   */
  to?: string;
  /** `NavbarSubmenuItem` children. */
  children: React.ReactNode;
}

// Each NavbarSubmenu instance owns a fully independent, self-contained
// Accordion.Root (never shared across sibling NavbarSubmenus), so a single
// constant item identity is all that's needed. `type="multiple"` (rather
// than `type="single"`) is used purely so this lone item can freely toggle
// open/closed on click without also needing a `collapsible` prop — RFC
// §3.6/§4.3, arbitrated by @sandy.
const ACCORDION_ITEM_VALUE = "submenu";

// Delay before a mouse-leave closes the flyout, long enough for the pointer
// to travel across the trigger→content gap (the validated opencti/openaev
// hover-to-open pattern, RFC §5.2). Click/keyboard open (Enter/Space/
// ArrowDown) and Escape-closes-and-returns-focus are entirely free from
// Radix's DropdownMenu.Trigger/Content — this timer only adds the mouse
// layer on top.
const HOVER_CLOSE_DELAY_MS = 150;

// Fidelity re-pass #2 point 3: node 5425:11518 confirms that when a
// descendant route is the active page (e.g. "Button" under "Components"),
// the PARENT trigger row also renders selected in collapsed mode, not just
// the leaf submenu item — so a collapsed user landing mid-navigation still
// sees which top-level section they're in. Checks each child's own
// `aria-current` first (direct `NavbarSubmenuItem aria-current="page"`
// usage), then one level deeper for the `asChild` + router-`Link`
// composition (`<NavbarSubmenuItem asChild><Link aria-current="page">`),
// matching the two ways a consumer can mark the active row.
function hasActiveDescendant(children: React.ReactNode): boolean {
  return React.Children.toArray(children).some((child) => {
    if (!React.isValidElement(child)) return false;
    const props = child.props as { "aria-current"?: unknown; children?: React.ReactNode };
    if (props["aria-current"] === "page") return true;
    const nested = props.children;
    if (React.isValidElement(nested)) {
      const nestedProps = nested.props as { "aria-current"?: unknown };
      if (nestedProps["aria-current"] === "page") return true;
    }
    return false;
  });
}

/**
 * Dual-mode submenu: renders as an inline WAI-ARIA disclosure (Radix
 * `Accordion`) while the ancestor `Navbar` is expanded, and as a `role="menu"`
 * flyout (Radix `DropdownMenu`, opened by click, keyboard, or hover) while
 * it's collapsed. The trigger in both modes IS a `NavbarItem` (composed via
 * `asChild`, not reimplemented) — see NavbarItem.rfc.md §4.3.
 *
 * Mode is always derived from `NavbarContext`; there is deliberately no prop
 * to force one mode manually (NavbarSubmenu.rfc.md §4.2) — a submenu can
 * never disagree with its own Navbar's collapse state.
 *
 * When `href`/`to` is set, the collapsed-mode trigger additionally becomes a
 * real, directly-navigable link (mirrors openaev's `MenuItemGroup` pattern,
 * §4.3/§5.2) — hover/focus still opens the flyout independently, and
 * clicking or pressing Enter navigates without also toggling it.
 * Expanded-mode behavior is entirely unaffected: `href`/`to` are ignored
 * there, a pure accordion toggle as before this feature.
 */
export function NavbarSubmenu({
  label,
  icon,
  open,
  defaultOpen = false,
  onOpenChange,
  href,
  to,
  children,
}: NavbarSubmenuProps): React.JSX.Element {
  const collapsed = useNavbarCollapsed();
  const isActiveDescendant = hasActiveDescendant(children);
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const isOpen = open ?? uncontrolledOpen;

  // Prop-contract violation (`href`/`to` documented mutually exclusive, see
  // the doc comments above) — dev-only diagnostic, same precedent as
  // `ProductSwitcher`'s `href`/`to` (AGENTS.md "Prop contract violations"):
  // warn, never throw, `href` still wins so behavior stays deterministic.
  if (typeof process !== "undefined" && process.env.NODE_ENV !== "production" && href && to) {
    console.warn(
      "NavbarSubmenu: both `href` and `to` are set, which are documented as mutually exclusive. `href` takes priority and `to` is ignored.",
    );
  }
  const linkHref = href ?? to;

  const setOpen = React.useCallback(
    (next: boolean) => {
      setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [onOpenChange],
  );

  const triggerRef = React.useRef<HTMLButtonElement>(null);

  // Tracks "is focus currently somewhere inside our open content" *live*,
  // via focus/blur events — not by querying `document.activeElement`, which
  // doesn't work here: switching `collapsed` swaps the whole
  // Accordion↔DropdownMenu JSX subtree, so by the time any effect runs,
  // React has already unmounted the old (focused) content and reset
  // `document.activeElement`. A ref updated in real time as focus moves
  // survives that unmount because it was written *before* it happened.
  const contentHasFocusRef = React.useRef(false);
  const handleContentFocus = React.useCallback(() => {
    contentHasFocusRef.current = true;
  }, []);
  const handleContentBlur = React.useCallback(() => {
    contentHasFocusRef.current = false;
  }, []);

  // Collapse-triggered close + focus-return (RFC §5.2): when the ancestor
  // Navbar flips to collapsed while focus sits inside this submenu's open
  // (accordion-mode) content, close it and hand focus back to our own
  // trigger rather than leaving it stranded on a node about to disappear
  // from the accessibility tree.
  //
  // This MUST close synchronously during render, not react afterwards in a
  // `useEffect` — Radix's `DropdownMenu.Content`, when it mounts already
  // `open`, auto-focuses into itself the instant it mounts (a layout
  // effect), which runs *before* a plain `useEffect` gets a chance to
  // close it back down. Reacting after the fact loses that race every
  // time. Deriving the closed state during render instead (the documented
  // React "adjusting state when a prop changes" pattern — a conditional,
  // render-phase `setState` call, guarded against re-firing by the ref
  // comparison below) means the flyout never mounts open in the first
  // place, so there's no auto-focus to race against.
  const prevCollapsedRef = React.useRef(collapsed);
  const pendingRefocusRef = React.useRef(false);
  const pendingOpenChangeNotifyRef = React.useRef(false);
  if (prevCollapsedRef.current !== collapsed) {
    const justCollapsed = collapsed && !prevCollapsedRef.current;
    prevCollapsedRef.current = collapsed;
    if (justCollapsed && contentHasFocusRef.current) {
      contentHasFocusRef.current = false;
      pendingRefocusRef.current = true;
      if (open === undefined) {
        // Uncontrolled: safe to adjust our own state mid-render.
        setUncontrolledOpen(false);
      } else {
        // Controlled: we can't force `open` closed ourselves — request it
        // from the owner via `onOpenChange`, deferred to an effect (calling
        // a parent-owned callback synchronously during render risks a
        // "Cannot update a component while rendering a different
        // component" warning if that callback itself calls setState).
        pendingOpenChangeNotifyRef.current = true;
      }
    }
  }

  React.useEffect(() => {
    if (pendingOpenChangeNotifyRef.current) {
      pendingOpenChangeNotifyRef.current = false;
      onOpenChange?.(false);
    }
  });

  React.useLayoutEffect(() => {
    if (pendingRefocusRef.current) {
      pendingRefocusRef.current = false;
      triggerRef.current?.focus();
    }
  });

  const closeTimerRef = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const cancelScheduledClose = React.useCallback(() => {
    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
  }, []);

  // Radix's DropdownMenuTrigger toggles open state unconditionally on
  // pointerdown, before its own click fires — confirmed by reading
  // @radix-ui/react-slot's `mergeProps`: unlike Radix's own internal
  // `composeEventHandlers`, Slot's merge calls *both* the child's handler
  // (ours, on the asChild `NavbarItem`) and the slot's own handler (the
  // Trigger's native toggle) unconditionally, so `event.preventDefault()`
  // in the child handler has no effect on whether the slot's handler runs
  // — it cannot be used to suppress Radix's toggle.
  //
  // Real mouse users always hover before clicking, so once `openOnHover`
  // has already opened the flyout, a click on the trigger triggers *two*
  // independent close attempts: (1) Radix's own native toggle (open→close)
  // and (2) its DismissableLayer's outside-pointerdown dismissal — Radix
  // normally avoids the latter by deferring its outside-pointerdown
  // listener registration until just after the content mounts, but that
  // guard assumes content only ever opens as a *direct* result of the same
  // click; since our content already mounted earlier from hover, that
  // listener has long since armed by the time this click happens, so it
  // fires too. Both routes end up calling `handleRadixOpenChange(false)`
  // synchronously in the same event-handling burst, so we swallow every
  // close request for that burst (cleared on the next tick), not just one.
  const justOpenedByHoverRef = React.useRef(false);
  const ignoreRadixToggleRef = React.useRef(false);

  const openOnHover = React.useCallback(() => {
    cancelScheduledClose();
    if (!isOpen) {
      justOpenedByHoverRef.current = true;
    }
    setOpen(true);
  }, [cancelScheduledClose, setOpen, isOpen]);
  const closeOnHoverLeave = React.useCallback(() => {
    cancelScheduledClose();
    closeTimerRef.current = setTimeout(() => setOpen(false), HOVER_CLOSE_DELAY_MS);
  }, [cancelScheduledClose, setOpen]);
  React.useEffect(() => cancelScheduledClose, [cancelScheduledClose]);

  // Consumes `justOpenedByHoverRef` on the trigger's own pointerdown (which
  // — per Slot's merge order — always runs before Radix's native toggle
  // handler within the same event) so only the *immediate* click that
  // follows a hover-open arms the swallow window; a later, separate click
  // (after the flag has already been consumed or never set) toggles
  // normally.
  const markPendingToggleFromHover = React.useCallback(() => {
    if (justOpenedByHoverRef.current) {
      justOpenedByHoverRef.current = false;
      ignoreRadixToggleRef.current = true;
      setTimeout(() => {
        ignoreRadixToggleRef.current = false;
      }, 0);
    }
  }, []);

  // Swallows a toggle attempt caused specifically by the link trigger's own
  // pointerdown/click (armed on every pointerdown of the link, regardless of
  // button/modifier — harmless if Radix's own guard would never have
  // toggled anyway, since the flag then just quietly expires unused). A
  // real anchor's click must always just navigate, never also flip the
  // flyout's open state, but Radix's Trigger still runs its own pointerdown
  // handler unconditionally through Slot's merge (same constraint documented
  // above for `ignoreRadixToggleRef`). Unlike `ignoreRadixToggleRef` (which
  // only swallows a *close* request following a hover-open), this swallows
  // BOTH directions unconditionally: clicking the link trigger must never
  // open OR close the flyout as a side effect of navigating — only
  // `openOnHover`/`closeOnHoverLeave` (and, while open, Escape/outside-click
  // via Radix's own DismissableLayer) should ever change its state. Only
  // ever armed from the link branch below (`linkHref` truthy), so this has
  // no effect at all on the pre-existing, non-link trigger.
  const suppressLinkToggleRef = React.useRef(false);
  const markSuppressToggleFromLink = React.useCallback(() => {
    suppressLinkToggleRef.current = true;
    setTimeout(() => {
      suppressLinkToggleRef.current = false;
    }, 0);
  }, []);

  const handleRadixOpenChange = React.useCallback(
    (next: boolean) => {
      if (suppressLinkToggleRef.current) {
        return;
      }
      if (!next && ignoreRadixToggleRef.current) {
        return;
      }
      setOpen(next);
    },
    [setOpen],
  );

  // Enter on the link trigger must navigate, not toggle. Radix's own
  // DropdownMenuTrigger keydown handler unconditionally preventDefaults
  // Enter/Space/ArrowDown and toggles open state for Enter/Space. Attached
  // *directly* on `DropdownMenuPrimitive.Trigger` (not nested on the
  // NavbarItem/anchor child, unlike the pointerdown handlers above), this
  // composes through Radix's *own* `composeEventHandlers` — which, unlike
  // `@radix-ui/react-slot`'s unconditional merge (see the comment on
  // `ignoreRadixToggleRef`), DOES check `event.defaultPrevented` before
  // running its own handler. Calling `preventDefault()` here therefore stops
  // Radix's toggle from ever firing for this key, so `suppressLinkToggleRef`
  // isn't needed for this path. The browser's own native "Enter activates a
  // focused anchor" default action is the same event and gets prevented
  // too, so navigation is replayed manually via a synthetic `.click()` — a
  // `click` event only, never `pointerdown`, so Radix's toggle can't
  // re-trigger from it either. Space/ArrowDown are deliberately left
  // untouched: Space doesn't activate a real `<a>` natively (only Enter
  // does), and ArrowDown still opening the flyout for keyboard browsing
  // without navigating is a useful, unproblematic addition, not something
  // this feature needs to remove. Only wired to the Trigger when `linkHref`
  // is set (see the JSX below), so this has no effect on the pre-existing,
  // non-link trigger either.
  const handleLinkTriggerKeyDown = React.useCallback((event: React.KeyboardEvent<HTMLElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      event.currentTarget.click();
    }
  }, []);

  if (collapsed) {
    return (
      // `modal={false}`: the default modal DropdownMenu traps focus and sets
      // `pointer-events: none` on the rest of the page while open — correct
      // for an action/context menu, but wrong for a persistent nav's hover
      // flyout, where the user must remain able to point at sibling nav
      // items (and the rest of the page) while this panel is open.
      <DropdownMenuPrimitive.Root open={isOpen} onOpenChange={handleRadixOpenChange} modal={false}>
        <DropdownMenuPrimitive.Trigger
          asChild
          ref={triggerRef}
          onKeyDown={linkHref ? handleLinkTriggerKeyDown : undefined}
        >
          {linkHref ? (
            // `NavbarItem asChild`: Slot merges `navbarItemClass`/aria-*
            // onto a real, hand-composed `<a>` — icon/label spans are
            // duplicated here (not reused from NavbarItem's own internal
            // rendering) because Slot can't inject wrapper markup around an
            // arbitrary child (NavbarItem.tsx's own `asChild` doc comment);
            // this mirrors exactly what NavbarItem's non-asChild branch
            // renders in collapsed mode (icon visible, label visually
            // hidden — collapsed is always true here, so `effectiveShowIcon`
            // is always true and the label is always `sr-only`), so a
            // future edit to NavbarItem's collapsed markup should double as
            // a reminder to keep this copy in sync.
            <NavbarItem
              asChild
              chevron
              aria-current={isActiveDescendant ? "page" : undefined}
              onMouseEnter={openOnHover}
              onMouseLeave={closeOnHoverLeave}
            >
              <a href={linkHref} onPointerDown={markSuppressToggleFromLink}>
                {icon && (
                  <span
                    className="inline-flex shrink-0 text-default-secondary group-data-[disabled]:text-default-disabled mr-0.5"
                    aria-hidden="true"
                  >
                    {icon}
                  </span>
                )}
                <span className="flex-1 truncate text-left sr-only">{label}</span>
              </a>
            </NavbarItem>
          ) : (
            <NavbarItem
              icon={icon}
              chevron
              aria-current={isActiveDescendant ? "page" : undefined}
              onMouseEnter={openOnHover}
              onMouseLeave={closeOnHoverLeave}
              onPointerDown={markPendingToggleFromHover}
            >
              {label}
            </NavbarItem>
          )}
        </DropdownMenuPrimitive.Trigger>
        <DropdownMenuPrimitive.Portal>
          <DropdownMenuPrimitive.Content
            side="right"
            align="start"
            sideOffset={8}
            onMouseEnter={openOnHover}
            onMouseLeave={closeOnHoverLeave}
            onFocus={handleContentFocus}
            onBlur={handleContentBlur}
            className={cn(
              // Fidelity re-pass #2 points 1/5: node 6301:10728 (flyout
              // reference) confirmed NO border, shadow, radius, or internal
              // padding — the panel is a flat 179px-wide fill, items running
              // edge-to-edge. `min-w-48` (192px) and the
              // border/shadow/rounded-sm/p-1 below were all invented in the
              // prior pass; replaced with the measured fixed width.
              "z-50 w-[179px]",
              // token-lint-allow(179px is the exact Figma-measured flyout width, node 6301:10728 — not a multiple of the 4px spacing scale, so no --spacing-* token fits; same category as LAYOUT.md's content-measure exceptions)
              "bg-elevation-default",
              // Same fade pattern as Tooltip.tsx, extended with
              // motion-reduce awareness per this component's RFC §3.5.
              "opacity-0 transition-opacity duration-150 motion-reduce:transition-none",
              "data-[state=open]:opacity-100 data-[state=closed]:opacity-0",
            )}
          >
            {React.Children.map(children, (child) => (
              <DropdownMenuPrimitive.Item asChild>{child}</DropdownMenuPrimitive.Item>
            ))}
          </DropdownMenuPrimitive.Content>
        </DropdownMenuPrimitive.Portal>
      </DropdownMenuPrimitive.Root>
    );
  }

  return (
    <AccordionPrimitive.Root
      type="multiple"
      value={isOpen ? [ACCORDION_ITEM_VALUE] : []}
      onValueChange={(value) => setOpen(value.includes(ACCORDION_ITEM_VALUE))}
    >
      <AccordionPrimitive.Item value={ACCORDION_ITEM_VALUE}>
        {/* asChild + plain <div>: Accordion.Header defaults to <h3>, which
            would introduce an unintended heading into the nav's document
            outline. A submenu trigger is a disclosure control, not content
            heading — WAI-ARIA disclosure pattern doesn't call for one. */}
        <AccordionPrimitive.Header asChild>
          <div>
            <AccordionPrimitive.Trigger asChild ref={triggerRef}>
              <NavbarItem
                icon={icon}
                chevron
                aria-current={isActiveDescendant ? "page" : undefined}
              >
                {label}
              </NavbarItem>
            </AccordionPrimitive.Trigger>
          </div>
        </AccordionPrimitive.Header>
        <AccordionPrimitive.Content
          className="overflow-hidden"
          onFocus={handleContentFocus}
          onBlur={handleContentBlur}
        >
          <div className="flex flex-col">{children}</div>
        </AccordionPrimitive.Content>
      </AccordionPrimitive.Item>
    </AccordionPrimitive.Root>
  );
}

NavbarSubmenu.displayName = "NavbarSubmenu";
