import * as React from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../../lib/cn";
import { Icon } from "../icon";
import { IconButton } from "../icon-button";

// ── Dialog Root / Trigger / Close ───────────────────────────────────────────
// Direct re-exports, no styling needed — matches Tabs precedent
// (`const Tabs = TabsPrimitive.Root`) and RFC §4.1. `modal` stays fixed to
// Radix's own default (`true`) — no non-modal usage found in any product
// (RFC §4.2/§7). That intent was previously documented only in this
// comment, not enforced: PR #51 review (Copilot, round 1, comment on this
// line) correctly flagged that `DialogPrimitive.Root`'s own props still
// allow `modal={false}` to be passed through, which would desync from
// `DialogContent`'s hard-coded `aria-modal="true"` below (real ARIA-
// semantics bug if that escape hatch were ever used). Fixed by re-typing
// `Dialog` to omit `modal` from its public props — runtime behavior is
// unchanged (still literally `DialogPrimitive.Root`); this only closes the
// gap between the RFC's already-decided "always modal" intent (§4.2/§7)
// and what TypeScript actually let a consumer pass. See the
// `@ts-expect-error` test in Dialog.keyboard.test.tsx (matches the
// existing precedent in Tabs.keyboard.test.tsx) for the compile-time
// proof this is now enforced.

const Dialog = DialogPrimitive.Root as React.FC<
  Omit<React.ComponentProps<typeof DialogPrimitive.Root>, "modal">
>;

const DialogTrigger = DialogPrimitive.Trigger;

const DialogClose = DialogPrimitive.Close;

// ── DialogOverlay (internal only, not exported) ─────────────────────────────
// Baked into DialogContent below, exactly matching TooltipContent's own
// precedent of wrapping TooltipPrimitive.Portal internally (RFC §4.3) —
// DialogPortal/DialogOverlay are not part of the public compound API.

const DialogOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    className={cn(
      "fixed inset-0 z-50",
      // RFC §3.4/§9 arbitration #11 (visual-fix-pass-1 correction, live
      // re-fetch of node 5476:11938 "overlay" inside mise-en-situation
      // 5138:38875 + master component 2879:22353): scrim color is
      // --bg-elevation-default-layer-0, at 80% opacity — confirmed via
      // get_variable_defs (bound var) AND get_design_context (rendered
      // "opacity-80" + screenshot). CORRECTS a bug shipped in the previous
      // pass: "bg-elevation-default-layer-0/80" (a bare custom-utility name
      // + /NN opacity modifier) generates ZERO CSS — verified empirically
      // by compiling this exact class with the Tailwind v4 CLI (`tailwindcss
      // -i src/tokens/index.css`) and finding no matching rule in the
      // output; this is exactly why the overlay was reported "manquant"
      // (missing), not a z-index or logic bug.
      //
      // A same-pass first attempt at fixing this
      // (`bg-[var(--bg-elevation-default-layer-0)]/80`) was ALSO wrong and
      // is called out here rather than silently swapped: `pnpm check:tokens`
      // (scripts/check-token-usage.ts) rejects it — its themeTokens set is
      // built from `theme.base.keys()` (scripts/lib/theme.ts loadTheme()),
      // and loadTheme() merges `:root {}` INTO `base` (not just `@theme {}`
      // as AGENTS.md's own table wording suggests in isolation), so
      // `--bg-elevation-default-layer-0` (declared in :root/.light/.dark)
      // counts as a "theme token" for this gate's purposes too — its
      // `[var(--x)]`-forbidding rule isn't @theme{}-only in practice.
      // Confirmed empirically (`pnpm check:tokens` failure), not just by
      // re-reading the script.
      //
      // Actual fix: the SAME `.layer-N` context-class mechanism used for
      // fix #1 (DialogContent's background, below) — `layer-0` re-points
      // the ambient --bg-elevation-default alias to layer-0's value for
      // this element, then the pre-existing `bg-elevation-default` @utility
      // (a plain, un-modified class — no token suffix, so untouched by the
      // check-token-usage.ts rule above) picks it up. The 80% dimming is
      // then native `opacity-*` on the whole element rather than a
      // color-alpha modifier — safe here because DialogOverlay has no
      // children/border/text of its own for `opacity` to over-affect, so a
      // whole-element opacity and a background-only alpha are visually
      // identical. This also conveniently folds the "80%" target into the
      // SAME classes already doing the open/close fade (below) instead of
      // stacking a second, conflicting opacity utility. All 3 candidates
      // (this one, the two rejected above) were compiled with the Tailwind
      // v4 CLI directly to confirm real output before choosing.
      "layer-0 bg-elevation-default",
      // RESOLVED (2026-07-27, PR #49 merged): --blur-sm (4px) landed in
      // theme.css's native `blur` namespace, generating `backdrop-blur-sm`
      // natively — the `dialog-tokens-consume` blocker is lifted for blur.
      // Value note: this is 4px, NOT the 2px this comment block previously
      // cited from the live Figma re-fetch (node 5476:11938/5476:11958,
      // re-checked again this pass — both STILL render `backdrop-blur-[2px]`
      // raw). Sandy's explicit instruction is to snap to the nearest real
      // system scale step (--blur-sm = 4px) instead of carrying a bespoke,
      // token-less 2px value forward — the same kind of deliberate
      // design-lead override already recorded for the footer gap and
      // close-icon size (Dialog.rfc.md §9 arbitrations #19/#20) — tracked
      // as arbitration #21, which supersedes #11's original 2px figure
      // (see RFC §3.4 for the superseding note). `backdrop-blur-sm` is a
      // real generated utility
      // class (native theme scale, not an arbitrary-value `[2px]`/`[4px]`),
      // so it also finally closes out the AI-BACKLOG "AppShell.tsx —
      // migrate backdrop-blur-[2px]" entry's blocking dependency (that
      // entry's own proposed name `--blur-global-overlay` did not ship —
      // corrected there to point at the real `--blur-sm`).
      "backdrop-blur-sm",
      // Open-state target is opacity-80 (not -100): this element's own
      // background is already fully opaque (see above), so the visible
      // "80%" scrim dimming happens here, on the whole-element opacity,
      // through the exact same classes that drive the enter/exit fade.
      "opacity-0 data-[state=open]:opacity-80 data-[state=closed]:opacity-0",
      "transition-opacity duration-150 motion-reduce:transition-none",
      className,
    )}
    {...props}
  />
));
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName;

// ── DialogContent ────────────────────────────────────────────────────────

const dialogContentVariants = cva(
  [
    "fixed left-1/2 top-1/2 z-50 -translate-x-1/2 -translate-y-1/2",
    "flex flex-col gap-6",
    // max-h-screen + overflow-hidden bounds the panel to the viewport so
    // DialogBody's own flex-1/overflow-y-auto (below) has real remaining
    // space to compute against and can actually take over scrolling
    // (RFC §3.6/§9 arbitration #10 — internal scroll, header/footer fixed,
    // page never scrolls). `fixed` above already establishes the
    // containing block the close button's `absolute` corner needs — no
    // separate `relative` class required. Native Tailwind utilities only,
    // no custom token needed for either.
    "max-h-screen overflow-hidden",
    // visual-fix-pass-1: panel background must resolve to #13213e — live
    // re-fetch of node 2879:22353 (master "md" component) confirms this via
    // TWO independent MCP calls: get_variable_defs on 2879:22352 returns
    // "var(--bg-elevation-default)":"#13213e", and get_design_context on
    // 2879:22353 shows `bg-[var(--bg-elevation-default,#13213e)]` — Figma's
    // own binding is the alias `--bg-elevation-default`, not a "-layer-2"
    // suffixed name. Confirmed in theme.css: :root/.dark's
    // --bg-elevation-default-layer-2 resolves to var(--grayblue-700) =
    // #13213e exactly (.light's equivalent is var(--gray-50), the correct
    // per-mode counterpart). The `layer-2` class below is the theme.css-
    // authored context class (":root"-sibling, unused elsewhere in this
    // codebase but purpose-built for exactly this) that locally re-points
    // --bg-elevation-default (and its heading/highlight/disabled/border
    // siblings) at the layer-2 values for this subtree — so the existing
    // `bg-elevation-default` utility class name below needs NO change, and
    // Dialog.meta.ts's contrastPairs literal token names (`bg:
    // "--bg-elevation-default"`) also stay unchanged — check-contrast.ts's
    // Rule 5 coverage check matches contrastPairs by the literal CSS custom
    // property name a class resolves through, not by the cascaded runtime
    // value, so the entries are correctly left as-is (see Dialog.meta.ts's
    // notes for the full reasoning and hand-verified real-vs-ambient ratio
    // numbers this cascade implies — no WCAG risk either way). Verified by
    // compiling both classes with the Tailwind v4 CLI directly
    // (`tailwindcss -i src/tokens/index.css`): `.layer-2{...}` and
    // `.bg-elevation-default{background-color:var(--bg-elevation-default)}`
    // both emit real rules. No theme.css edit, no new token — AGENTS.md
    // line 162 forbids agent-authored tokens; this needed none.
    "layer-2",
    "bg-elevation-default text-default-primary rounded-sm shadow-global-shadow p-6",
    "opacity-0 data-[state=open]:opacity-100 data-[state=closed]:opacity-0",
    "transition-opacity duration-150 motion-reduce:transition-none",
  ],
  {
    variants: {
      size: {
        // RESOLVED (2026-07-27, PR #49 merged): the `dialog-tokens-consume`
        // blocker is lifted. Landed tokens are --width-overlay-sm/md/lg/xl
        // (420/640/960/1360px — sm/md/lg match arbitration #4 exactly),
        // native `width` namespace, exposed via Thibault's custom
        // `w-overlay-*` @utility. Mechanism note: this is a FIXED width
        // (`width:`), NOT the max-w-dialog-*/`--container-*` max-width
        // mechanism this comment originally anticipated — Sandy confirmed
        // fixed width is the correct, deliberate choice (no responsive
        // shrink-below-breakpoint behavior wanted), so `w-overlay-*` is
        // used as-is rather than routed through a max-width wrapper.
        sm: "w-overlay-sm",
        md: "w-overlay-md",
        lg: "w-overlay-lg",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface DialogContentProps
  extends
    React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>,
    VariantProps<typeof dialogContentVariants> {
  /**
   * Hides the built-in corner close icon. Mirrors Figma's own `hasClose`
   * toggle (Dialog.rfc.md §3.1) — visible by default, conforming to Figma
   * over openaev's inverted wrapper convention (arbitration #5).
   */
  hideCloseButton?: boolean;
}

/**
 * True if `node` contains an element of the given compound sub-component,
 * at any depth (not just a direct child) — so a `DialogTitle` wrapped in
 * Radix's `VisuallyHidden` (the exact pattern our own dev warning below
 * recommends for a visually-hidden-but-present title) is still found
 * instead of producing a false-positive warning.
 */
function hasDescendantOfType(node: React.ReactNode, type: React.ElementType): boolean {
  return React.Children.toArray(node).some((child) => {
    if (!React.isValidElement(child)) {
      return false;
    }
    if (child.type === type) {
      return true;
    }
    const childProps = child.props as { children?: React.ReactNode };
    return hasDescendantOfType(childProps.children, type);
  });
}

const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  DialogContentProps
>(({ className, size, hideCloseButton = false, children, ...props }, ref) => {
  // Prop-contract dev warning (AGENTS.md "Prop contract violations" —
  // ProductSwitcher href/to precedent, PR #43 review C2): DialogContent
  // without a DialogTitle still renders (Radix doesn't throw), but the
  // dialog has no accessible name (WCAG 2.4.6/4.1.2). Dev-only, never
  // throws; production builds strip this via the usual NODE_ENV
  // dead-code elimination.
  //
  // Empirically verified against the installed @radix-ui/react-dialog
  // (1.1.22, dist/index.mjs): it has NO built-in dev warning for a
  // missing Title or Description — the package's exported
  // `WarningProvider` is a plain pass-through (`(props) => props.children`),
  // and `aria-labelledby`/`aria-describedby` are silently omitted
  // (`void 0`) when the corresponding sub-component isn't mounted, with
  // no console output either way. This supersedes Dialog.rfc.md §5.3's
  // original (unverified) assumption that Radix warns for a missing
  // Description — corrected there in the same commit as this file. FDS's
  // own warning below is therefore the ONLY missing-Title signal a
  // consumer gets; nothing to suppress or de-duplicate for Description
  // (optional per RFC §4.1/§4.2 — silently absent is correct, expected
  // behavior, not a contract violation).
  //
  // Corrected (PR #51 review, round 3 — Copilot, low-confidence suppressed
  // comment): `process.env.NODE_ENV` was read unguarded. `&&` evaluates
  // left-to-right, so this line threw `ReferenceError: process is not
  // defined` on every DialogContent render (Title present or not) in any
  // runtime with no `process` global — same established risk already
  // guarded in this package's `NavbarItem.tsx` and
  // `ProductSwitcher.tsx` (`typeof process !== "undefined"`, PR #43 round
  // 3). Dialog was the only component missing this guard. Matches that
  // exact precedent; proven with the same `vi.stubGlobal("process",
  // undefined)` regression pattern in `Dialog.keyboard.test.tsx`.
  if (
    typeof process !== "undefined" &&
    process.env.NODE_ENV !== "production" &&
    !hasDescendantOfType(children, DialogTitle)
  ) {
    console.warn(
      "[Dialog] DialogContent was rendered without a DialogTitle child. " +
        "The dialog will still open and function, but has no accessible name " +
        "(WCAG 2.4.6, 4.1.2). Add a DialogTitle — wrap it in Radix's " +
        "VisuallyHidden if it shouldn't be shown visually, never omit it.",
    );
  }

  return (
    <DialogPrimitive.Portal>
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={ref}
        {...props}
        // Dialog.rfc.md §5.1 states this dialog is `role="dialog"
        // aria-modal="true"` per the WAI-ARIA Dialog Modal pattern — that
        // assumption was written as "Radix sets this automatically", which
        // is empirically wrong: @radix-ui/react-dialog@1.1.22 (dist/
        // index.mjs) never sets `aria-modal` anywhere; it achieves the
        // equivalent outcome for AT users via `aria-hidden` + pointer-events
        // on background siblings instead (its own inert-background
        // mechanism), but that isn't a substitute for the explicit
        // attribute some assistive tech keys off directly. Set explicitly
        // here rather than relying on a primitive that doesn't provide it —
        // corrects §5.1 in the same commit as this fix.
        //
        // Corrected (PR #51 review round 2 — Copilot, low-confidence
        // suppressed comment on this line): `{...props}` must be spread
        // BEFORE `aria-modal`, not after — object/JSX spread means later
        // keys win, so with the previous order a consumer passing their own
        // `aria-modal` prop (allowed by `React.AriaAttributes`, which
        // TypeScript can't exclude the same way the `modal` fix above did)
        // would have silently overridden this hard-coded value. Empirically
        // reproduced before this fix: rendering
        // `<DialogContent aria-modal={false}>` produced a real DOM
        // `aria-modal="false"`. `aria-modal` (and `className` right below)
        // are placed after the spread specifically so neither can be
        // overridden — same "always modal" intent as RFC §4.2/§7, now also
        // closed for `DialogContent`'s own props, not just `Dialog`'s.
        // Covered by Dialog.keyboard.test.tsx.
        aria-modal="true"
        className={cn(dialogContentVariants({ size }), className)}
      >
        {!hideCloseButton && (
          <DialogPrimitive.Close asChild>
            <IconButton
              icon={<Icon name="x" size={24} aria-hidden />}
              aria-label="Close"
              priority="tertiary"
              // visual-fix-pass-1 point 4: switched sm (24×24px) → the
              // IconButton default, size="md" (36×36px) — IconButton.meta.ts
              // line 29 / IconButton.rfc.md §3.1 document "md" as the prop's
              // documented default (`defaultVariants.size` in
              // IconButton.tsx). Icon bumped 16px→24px to match, per
              // IconButton's own documented size↔icon pairing (RFC: "Size=md
              // | 36×36px, icon 24px").
              // FIGMA DISCREPANCY (flagging per instructions, not silently
              // resolving): re-fetching the close-icon node this pass
              // (5476:11939;2906:5796 in the mise-en-situation, and
              // 2906:5807 in the master component 2879:22353) both still
              // measure a 24×24px container — i.e. Figma's own spec for
              // this exact close button matches "sm", not "md". Applied the
              // explicit "not small" instruction as the deliberate
              // override; no Figma variant at 36×36px exists to verify an
              // md-sized close button against, so the 10px inset below is
              // unverified at this new size (kept as-is — only the size
              // prop was in scope here). Formalized as Dialog.rfc.md §9
              // arbitration #20 — Dialog.figma.json's "close icon"
              // expectedClasses updated accordingly (values/tokens kept at
              // the raw Figma sm/24px measurement for provenance).
              size="md"
              // 10px inset (spacing-2.5, native Tailwind scale) — RFC
              // §3.3: "24×24px, inset 10px from top and right in all 3
              // sizes" (that Figma spec is for the "sm"-sized close button;
              // see discrepancy note above). Absolute within DialogContent
              // (`fixed` above is its own containing block), outside the
              // gap-6 flex flow, matching Figma's corner-anchored placement.
              className="absolute top-2.5 right-2.5"
            />
          </DialogPrimitive.Close>
        )}
        {children}
      </DialogPrimitive.Content>
    </DialogPrimitive.Portal>
  );
});
DialogContent.displayName = DialogPrimitive.Content.displayName;

// ── DialogTitle ──────────────────────────────────────────────────────────
// Styled with Text's exact title-sm utility classes (Dialog.rfc.md §3.4) —
// classes copied directly onto the Radix primitive rather than nesting the
// real `<Text>` component inside, matching TooltipContent's own established
// precedent (content-compact classes applied the same way) instead of
// introducing a new asChild+Text nesting pattern with no prior use in this
// codebase.

const DialogTitle = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    className={cn(
      "font-title-sm font-bold text-title-sm leading-title-sm tracking-title-sm",
      "text-default-primary",
      // Unconditional pr-8 (32px, native Tailwind spacing scale) reserves
      // room so a long title doesn't run under the absolute close-icon
      // corner (24px icon + 10px inset). Harmless when hideCloseButton is
      // set (a few px of unused padding on an otherwise short title) —
      // not worth threading that prop across sibling components for a
      // cosmetic edge case Figma doesn't itself demonstrate (RFC §3.6).
      // Flagged for a look during the STOP #2 visual pass.
      "pr-8",
      className,
    )}
    {...props}
  />
));
DialogTitle.displayName = DialogPrimitive.Title.displayName;

// ── DialogDescription ────────────────────────────────────────────────────
// Optional short subtitle only — NOT the main body (RFC §4.1/§4.2). Styled
// with Text's content-base variant classes, same direct-class-copy approach
// as DialogTitle above.

const DialogDescription = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    className={cn(
      "font-content-base text-content-base leading-content-base tracking-content-base",
      "text-default-primary",
      className,
    )}
    {...props}
  />
));
DialogDescription.displayName = DialogPrimitive.Description.displayName;

// ── DialogBody ───────────────────────────────────────────────────────────
// FDS-only addition, no direct Figma node or Radix equivalent — needed to
// deliver arbitration #10's resolved behavior ("header and footer stay
// fixed, body scrolls") given the approved §4.1 API keeps DialogTitle/
// DialogDescription/free content/DialogFooter as flat siblings: without a
// dedicated scrollable wrapper for the free-form middle content, there is no
// way to bound only that region's overflow independently of Title/Footer.
// Confirmed via arbitration this session (see Dialog.rfc.md's updated
// §3.6/§4.1 note) rather than letting the whole panel scroll as one block. `min-h-0` overrides flexbox's default
// min-height:auto so the flex-1 region can actually shrink below its
// content's intrinsic height and hand overflow to its own scrollbar instead
// of forcing DialogContent (capped at max-h-screen) to grow past the
// viewport.

const DialogBody = React.forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("flex-1 min-h-0 overflow-y-auto", className)} {...props} />
  ),
);
DialogBody.displayName = "DialogBody";

// ── DialogFooter ──────────────────────────────────────────────────────────
// FDS-only addition, no Radix equivalent (RFC §4.1/§4.3) — thin wrapper,
// `justify-end` + normal (non-reversed) DOM order means whatever the
// consumer lists LAST renders rightmost — Dialog.meta.ts's demos all list
// [DialogClose/secondary, primary] in that order, i.e. secondary/cancel
// left, primary/confirm right already, structurally (to be confirmed with
// an actual screenshot this same pass) — no order change made here.
//
// visual-fix-pass-1 point 3: previous 16px spacing class → gap-2 (8px,
// native Tailwind v4 spacing scale, --spacing base = 4px per
// theme.css:189 — no new token).
// FIGMA DISCREPANCY (flagging per instructions, not silently resolving):
// re-fetching the "Button group" node this pass — both
// 5476:11939;2879:22300 in the mise-en-situation AND 2879:22358 in the
// master component 2879:22353 — measure 16px (Figma's four-times-spacing
// token), not 8px. Applied the explicit 8px instruction as the deliberate
// override (a real, existing token — gap-2 — either way, never a
// hardcoded px value). NOTE: this comment intentionally never spells out
// the literal previous class name as a bare substring — doing so once
// silently masked scripts/check-figma-fidelity.ts's literal-substring
// `expectedClasses` check (it matched the OLD class name inside this
// very comment, not in the rendered code, producing a false PASS on the
// "footer" variant; caught and fixed in this same commit — see
// Dialog.figma.json's updated note and Dialog.rfc.md §9 arbitration #19).

const DialogFooter = React.forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      className={cn("flex items-center justify-end gap-2 w-full", className)}
      {...props}
    />
  ),
);
DialogFooter.displayName = "DialogFooter";

export {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogTitle,
  DialogDescription,
  DialogBody,
  DialogFooter,
  DialogClose,
};
