// Real product wordmark logos (fidelity re-pass #2 point 10) — downloaded from
// Figma node 2624:11345 ("Design_System_2026", file 0PmhuZzF9XcaIEfMMW2a51),
// stored as static assets at docs/public/product-logos/*.svg (same pattern as
// the pre-existing docs/public/filigran-{light,dark}.svg) and also surfaced
// in docs/app/tokens/page.tsx's "Product Logos" section for discoverability.
// h-7 (28px): fidelity re-pass #4 point 4 — Figma node 6332:10103 measures
// the trigger's own logo slot at exactly 28px tall (was h-5/20px, an
// unverified guess from an earlier pass).
//
// basePath: this file lives in the design-system PACKAGE, not docs/, so it
// cannot import the docs-only docs/lib/base-path.ts helper (that would be a
// backwards package→docs dependency) — inlined here instead, mirroring that
// file's own NEXT_PUBLIC_BASE_PATH-first / BASE_PATH-fallback / ""-default
// resolution exactly so both stay equivalent if a subpath is ever
// reintroduced (see base-path.ts's comment for why NEXT_PUBLIC_* is checked
// first). Guarded with `typeof process !== "undefined"`: unlike docs/, which
// only ever runs inside Next.js, this package file could in principle be
// consumed by a bare bundler/runtime with no `process` global at all.
const basePath =
  (typeof process !== "undefined"
    ? (process.env.NEXT_PUBLIC_BASE_PATH ?? process.env.BASE_PATH)
    : undefined) ?? "";

function productLogo(name: string) {
  return h("img", {
    src: `${basePath}/product-logos/${name}.svg`,
    alt: "",
    className: "h-7 w-auto",
  });
}

