import * as React from "react";

import { cn } from "../../lib/cn";
import { Icon } from "../icon";
import { NavbarItem } from "../navbar-item/NavbarItem";
import { NavbarContext } from "./NavbarContext";

export interface NavbarProps extends React.ComponentPropsWithoutRef<"nav"> {
  /**
   * Accessible landmark name (required, not defaulted — Navbar.rfc.md §5.3).
   * Every product renders more than one `<nav>` on the page, so a
   * distinguishing name is mandatory, and the exact wording is
   * product/locale-specific.
   */
  "aria-label": string;
  /** Controlled collapsed state. Omit for uncontrolled (see `defaultCollapsed`). */
  collapsed?: boolean;
  /** Initial collapsed state for uncontrolled usage. Default: `false`. */
  defaultCollapsed?: boolean;
  /** Notifies on user-driven collapse/expand (footer toggle click). */
  onCollapsedChange?: (collapsed: boolean) => void;
  /** Header slot — typically a `<ProductSwitcher>` (§3.2 `productLogo`). */
  header?: React.ReactNode;
  /** Main content — `NavbarItem` / `NavbarSubmenu` / `NavbarSeparator` children. */
  children: React.ReactNode;
  /**
   * Footer slot rendered above the built-in collapse toggle (e.g. a
   * help/settings `NavbarItem`). The toggle itself is always rendered by
   * `Navbar` and is not user-supplied — its icon/label are state-driven
   * (§4.2).
   */
  footer?: React.ReactNode;
}

/**
 * The primary structural navigation container (Navbar.rfc.md) — a thin
 * composition root, not a monolith: it owns the collapsed/expanded state,
 * the `<nav>` landmark, the width transition, and the footer collapse
 * toggle, sharing `collapsed` with its descendants (`NavbarItem`,
 * `NavbarSubmenu`, `ProductSwitcher`) via `NavbarContext` rather than
 * rendering their content itself (§1/§4.3).
 */
export const Navbar = React.forwardRef<HTMLElement, NavbarProps>(
  (
    {
      className,
      collapsed: collapsedProp,
      defaultCollapsed = false,
      onCollapsedChange,
      header,
      children,
      footer,
      ...props
    },
    ref,
  ) => {
    const [uncontrolledCollapsed, setUncontrolledCollapsed] = React.useState(defaultCollapsed);
    const collapsed = collapsedProp ?? uncontrolledCollapsed;

    const handleToggle = React.useCallback(() => {
      const next = !collapsed;
      if (collapsedProp === undefined) {
        setUncontrolledCollapsed(next);
      }
      onCollapsedChange?.(next);
    }, [collapsed, collapsedProp, onCollapsedChange]);

    return (
      <NavbarContext.Provider value={{ collapsed }}>
        <nav
          ref={ref}
          className={cn(
            "flex h-full flex-col justify-between overflow-hidden",
            // No border-r: fidelity re-pass #2 (node 5425:11608, the real
            // OpenCTI-integrated frame) confirmed the panel's right edge is
            // a plain background-color transition — pixel-sampled, no
            // distinct stroke color exists. The prior `border-r
            // border-elevation-default` was invented (§ report point 1).
            //
            // Fidelity re-pass #3 point 2: node 5425:11518/5425:11608
            // confirmed the panel's fill is the two-stop dark gradient
            // (--bg-elevation-default-layer-0 #070d18 -> -layer-0-gradient
            // #0c1527), not the flat --bg-elevation-default solid used
            // previously.
            //
            // Fidelity re-pass #4 point 1: the token's angle was wrongly set
            // to 135deg (an invented "average" of 3 differently-shaped
            // frames' resampled exports — 91.9/105.7/160.86deg — none of
            // which is actually 135). At 135deg on a tall/narrow fixed-width
            // panel, the transition stretches across the variable viewport
            // height, making the ~5% RGB delta imperceptible in the visible
            // fold (measured: rgb(7,14,25)->rgb(11,20,37) over 900px,
            // Playwright pixel sample). The Navbar's own node (5425:11608)
            // measures 91.9166deg — i.e. ~90deg, matching the codebase's
            // other 3 gradient tokens (gradient-focus/warning/ia, all
            // exactly 90deg). Corrected --gradient-default to 90deg: the
            // transition now runs across the fixed width (180px/48px),
            // rendering consistently and visibly regardless of nav height.
            "bg-gradient-default",
            // Width is the only Navbar-owned transition (§3.5): 150ms,
            // Tailwind's default easing (same curve family as opencti's own
            // 225ms transition, but reused from Tooltip's already-proven
            // 150ms duration instead of opencti's, since opencti's never
            // respects prefers-reduced-motion — repo-wide grep confirmed
            // zero matches). First `prefers-reduced-motion` support in FDS.
            "transition-[width] duration-150 motion-reduce:transition-none",
            collapsed ? "w-12" : "w-45",
            className,
          )}
          {...props}
        >
          <div className="flex min-h-0 flex-1 flex-col">
            {/*
             * Re-verified against node 2843:5134 ("collapseState=close,
             * Product=OpenCTI") — the previous pl-4/pr-2-in-both-states
             * claim here was wrong and is corrected now. Figma's own
             * `productLogo` row switches layout strategy by state: expanded
             * uses `justify-between pl-4 pr-1` (logo left-anchored, chevron
             * pushed right); collapsed uses `justify-center px-0` (the
             * 28px-square picto centered across the full 48px rail, NOT
             * left-anchored under pl-4). Centering only in collapsed mode is
             * what actually lines the picto up with item icons below it —
             * those reach the same visual center via their own row's pl-4/
             * pr-2 padding leaving exactly a 16px content box (48-16-8) that
             * the icon fills edge-to-edge, i.e. a left-anchor and a center
             * converge only once the reduced content box is exactly
             * icon-sized. Left-anchoring the wider 28px logo the same way
             * (as before) shifted its visual center ~6px right of the icons'.
             */}
            {header && (
              <div
                className={cn(
                  "flex h-17 shrink-0 items-center",
                  collapsed ? "justify-center px-0" : "justify-between pl-4 pr-1",
                )}
              >
                {header}
              </div>
            )}
            <div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">{children}</div>
          </div>
          <div className="flex shrink-0 flex-col gap-1 py-2">
            {footer}
            <NavbarItem
              icon={<Icon name={collapsed ? "panel-left-open" : "panel-left-close"} size={16} />}
              onClick={handleToggle}
            >
              {/* opencti's real footer row (LeftBar.jsx:812-814) keeps a
                  static "Collapse" label even once collapsed (icon swaps,
                  text doesn't) — misleading as an accessible name once the
                  next action is actually "expand" (same class of issue as
                  the Collapse/Expand clash already corrected on
                  ProductSwitcher's own chevron, §5.3 of that RFC). Not
                  reproduced as-is; state-dependent label instead. */}
              {collapsed ? "Expand" : "Collapse"}
            </NavbarItem>
          </div>
        </nav>
      </NavbarContext.Provider>
    );
  },
);

Navbar.displayName = "Navbar";

export interface NavbarSeparatorProps extends React.ComponentPropsWithoutRef<"hr"> {}

/**
 * Divider between item groups (§3.2, §4.3 — 4 separators split ~19 items
 * into 5 groups in the Figma frame). Internal to `Navbar`, no dedicated RFC
 * section or ROADMAP entry per @sandy's explicit arbitration. A native
 * `<hr>` already computes an implicit `role="separator"` — no explicit
 * `role` attribute needed (and `eslint-plugin-jsx-a11y`'s
 * `no-redundant-roles` rule disallows adding one).
 */
export const NavbarSeparator = React.forwardRef<HTMLHRElement, NavbarSeparatorProps>(
  ({ className, ...props }, ref) => (
    <hr
      ref={ref}
      // Fidelity re-pass #3 point 5: node 5425:11518 confirms each "navbar
      // menu separator" instance is a zero-height, w-full line inside a
      // w-[179px] (full row width) wrapper with ONLY vertical padding
      // (py-2/8px) — no horizontal inset at all, unlike "navbar menu item"
      // rows, which are also w-[179px] outwardly but push their OWN
      // pl-4/pr-2 padding onto the inner <button>. The previous `mx-4` here
      // was invented (§ report point 5) and made the line stop short of
      // both edges instead of running edge-to-edge; the parent content
      // list (py-2 only, no horizontal padding — see the wrapping <div> in
      // Navbar above) means a plain `w-full` (no horizontal margin) already
      // spans the exact 180px/48px nav width in both collapsed and
      // expanded modes, with no separate collapsed-mode override needed.
      className={cn("my-2 w-full border-t border-elevation-subtle", className)}
      {...props}
    />
  ),
);

NavbarSeparator.displayName = "NavbarSeparator";
