import * as React from "react";
import { cva } from "class-variance-authority";

import { cn } from "../../lib/cn";
import { iconRegistry, type IconComponent, type IconName } from "./icon-registry.generated";

/** Allowed rendered sizes (px) — the only sizes designed in Figma. */
export const ICON_SIZES = [16, 20, 24] as const;
export type IconSize = (typeof ICON_SIZES)[number];

/** Decorative gradient fills (AI / focus accents). */
export type IconGradient = "ia" | "focus";

// Sizes map to Tailwind's native spacing scale (--spacing = 4px, imported via
// src/tokens/index.css). size-4/5/6 resolve to 16/20/24px via calc(--spacing * N).
const iconVariants = cva("inline-block shrink-0", {
  variants: {
    size: {
      16: "size-4",
      20: "size-5",
      24: "size-6",
    },
  },
  defaultVariants: {
    size: 24,
  },
});

interface IconBaseProps {
  /** Icon identifier from the generated design-system vocabulary (ICON_NAMES). */
  name: IconName;
  /** Rendered size in px (default 24). */
  size?: IconSize;
  /**
   * Decorative gradient fill. Gradient icons are visual accents: their
   * contrast against arbitrary backgrounds is NOT guaranteed (WCAG 1.4.11),
   * so never rely on a gradient icon alone to convey meaning.
   */
  gradient?: IconGradient;
  className?: string;
}

interface DecorativeIconProps extends IconBaseProps {
  /** Decorative is the default: hidden from assistive technologies. */
  "aria-label"?: never;
  "aria-hidden"?: true;
}

interface SemanticIconProps extends IconBaseProps {
  /** Standalone semantic icon: accessible name, rendered with role="img". */
  "aria-label": string;
  "aria-hidden"?: false;
}

export type IconProps = DecorativeIconProps | SemanticIconProps;

/**
 * Single entry point for icon rendering: Lucide glyphs and Filigran custom
 * glyphs behind one string-name API. Color is inherited from the CSS text
 * color (currentColor) — style it with text-* token classes on the icon or
 * a parent, never with hardcoded values.
 */
export function Icon(props: IconProps): React.JSX.Element {
  const { name, size = 24, gradient, className } = props;
  const ariaLabel = "aria-label" in props ? props["aria-label"] : undefined;
  // useId may contain characters invalid in a url(#…) reference — strip them.
  const maskId = `icon-gradient-${React.useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const Glyph: IconComponent | undefined = iconRegistry[name];
  if (!Glyph) {
    // Type-safe consumers can never reach this; it fails loudly for
    // untyped (plain JS) consumers instead of rendering nothing.
    throw new Error(
      `[Icon] Unknown icon name "${String(name)}". The vocabulary is the ICON_NAMES ` +
        `export from "@filigran/design-system" (generated — includes every valid IconName).`,
    );
  }

  const a11yProps = ariaLabel
    ? ({ role: "img", "aria-label": ariaLabel } as const)
    : ({ "aria-hidden": true } as const);

  if (gradient) {
    return (
      <span {...a11yProps} className={cn(iconVariants({ size }), "relative", className)}>
        <svg width="0" height="0" aria-hidden="true" className="absolute">
          <defs>
            <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width={size} height={size}>
              {/* "white" is the fully-visible mask luminance — a functional
                  value required by SVG masking, not a design color. */}
              <Glyph width={size} height={size} color="white" />
            </mask>
          </defs>
        </svg>
        <span
          className={cn(
            "absolute inset-0",
            gradient === "ia" ? "bg-gradient-ia" : "bg-gradient-focus",
          )}
          style={{ mask: `url("#${maskId}")`, WebkitMask: `url("#${maskId}")` }}
        />
      </span>
    );
  }

  return (
    <Glyph
      width={size}
      height={size}
      {...a11yProps}
      className={cn(iconVariants({ size }), className)}
    />
  );
}
