import { createElement as h } from "react";
import type { ComponentMeta } from "../../types/meta";
import { Icon } from "./Icon";
import { ICON_NAMES } from "./icon-registry.generated";

// Counts derived from the generated registry so this contract can never
// drift from the actual vocabulary (arbitrations change the numbers).
const customCount = ICON_NAMES.filter((name) => name.startsWith("custom/")).length;
const lucideCount = ICON_NAMES.length - customCount;

export const IconMeta: ComponentMeta = {
  name: "Icon",
  description: `Single entry point for icon rendering in the design system. Resolves a string name against the generated icon registry: ${lucideCount} Lucide glyphs (named imports — tree-shakeable) plus ${customCount} Filigran custom glyphs (custom/* prefix, currentColor). Decorative by default; semantic with aria-label.`,
  status: "stable",
  version: "0.1.0",
  radixPrimitive: "none",
  figmaLink:
    "https://www.figma.com/design/0PmhuZzF9XcaIEfMMW2a51/Design_System_2026?node-id=5642-192",
  figmaNodeId: "5642:192",
  variants: ["default", "gradient-ia", "gradient-focus"],
  sizes: ["16", "20", "24"],
  examples: [
    '// Decorative (default): hidden from assistive technologies\n<Icon name="search" />',
    '// Standalone semantic icon: accessible name + role="img"\n<Icon name="circle-alert" aria-label="Warning" />',
    '// Custom Filigran glyph — recolorable through the text color (currentColor)\n<span className="text-default-secondary">\n  <Icon name="custom/malware" size={16} />\n</span>',
    '// Decorative gradient accent (AI feature affordance)\n<Icon name="bolt" gradient="ia" />',
  ],
  render() {
    const label = (text: string) =>
      h(
        "p",
        {
          className:
            "text-content-caption font-content-caption leading-content-caption tracking-content-caption text-default-secondary",
        },
        text,
      );
    const row = (children: ReturnType<typeof h>[]) =>
      h("div", { className: "flex items-center gap-4 text-default-primary" }, ...children);

    return h(
      "div",
      { className: "flex flex-col gap-6" },
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Sizes — 16 / 20 / 24 (token classes size-4/5/6)"),
        row([
          h(Icon, { name: "search", size: 16 }),
          h(Icon, { name: "search", size: 20 }),
          h(Icon, { name: "search", size: 24 }),
        ]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Lucide set (sample) — color inherited via currentColor"),
        row([
          h(Icon, { name: "bell" }),
          h(Icon, { name: "calendar" }),
          h(Icon, { name: "chart-column" }),
          h(Icon, { name: "shield-check" }),
          h(Icon, { name: "settings" }),
          h(Icon, { name: "trash-2" }),
        ]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Custom Filigran glyphs (sample) — custom/* names"),
        row([
          h(Icon, { name: "custom/filigran" }),
          h(Icon, { name: "custom/malware" }),
          h(Icon, { name: "custom/intrusion-set" }),
          h(Icon, { name: "custom/opencti" }),
          h(Icon, { name: "custom/xtmone" }),
          h(Icon, { name: "custom/slack" }),
        ]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label('Semantic — aria-label + role="img" (inspect the DOM)'),
        row([h(Icon, { name: "circle-alert", "aria-label": "Warning" })]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Gradient accents (decorative only) — ia / focus"),
        row([
          h(Icon, { name: "bolt", gradient: "ia" }),
          h(Icon, { name: "custom/filigran", gradient: "ia" }),
          h(Icon, { name: "bolt", gradient: "focus" }),
          h(Icon, { name: "custom/filigran", gradient: "focus" }),
        ]),
      ),
    );
  },
  props: {
    name: 'IconName (required) — icon identifier from the generated vocabulary (ICON_NAMES export). Lucide glyphs use their kebab-case Lucide name (e.g. "chevron-down"); Filigran glyphs use the custom/ prefix (e.g. "custom/malware"). Unknown names throw.',
    size: "16 | 20 | 24 — rendered size in px, mapped to token classes size-4/5/6 (default: 24).",
    gradient:
      '"ia" | "focus" — decorative gradient fill via the bg-gradient-ia / bg-gradient-focus token utilities and an SVG luminance mask. Gradient icons are visual accents: never the sole carrier of meaning.',
    "aria-label":
      'string — accessible name for a STANDALONE semantic icon; adds role="img" and removes aria-hidden. Omit it (decorative default) when the icon accompanies visible text.',
    "aria-hidden":
      "boolean — true by default (decorative). Typing forbids aria-hidden={false} without an aria-label.",
    className:
      "string — extra token classes (e.g. text-feedback-error-primary to color the icon). Color always flows through currentColor.",
  },
  accessibility: {
    wcag: "2.1 AA",
    wcagStatus: "pass",
    contrastPairs: [
      {
        id: "semantic icon (primary text color)",
        fg: "--text-default-primary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
      {
        id: "semantic icon (secondary text color)",
        fg: "--text-default-secondary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
    ],
    notes:
      "Criteria: 1.1.1 Non-text Content — decorative by default: aria-hidden='true' unless an aria-label is provided; the props type forbids a semantic icon without an accessible name. " +
      "4.1.2 Name, Role, Value — semantic icons render role='img' + aria-label on the SVG (or on the gradient wrapper). " +
      "1.4.11 Non-text Contrast — icons inherit currentColor; the declared pairs prove the documented text-color tokens reach ≥ 3:1 on the page background in both modes (computed in CI by check-contrast). " +
      "Gradient icons (gradient='ia'|'focus') are decorative accents: gradient stops are NOT verified against arbitrary backgrounds, so a gradient icon must never be the sole carrier of meaning — pair it with text or a semantic sibling. " +
      "2.1.1 Keyboard — not applicable: Icon renders static, non-interactive SVG (no focusable content, no keyboard test needed); interactive behaviour belongs to the wrapping component (e.g. IconButton). " +
      "Custom glyphs are generated with fill='currentColor' (hardcoded fills stripped at generation), so light/dark rendering follows the text color tokens. " +
      "wcagStatus 'pass' basis: axe-core conformity suite reports 0 violations in both modes on the full render() surface (S1), and both declared contrast pairs are computed from tokens in CI (Q2). Automated checks cover ~half of WCAG — human/screen-reader audit cadence still applies per release.",
  },
};
