import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../../lib/cn";
import { Icon } from "../icon";

const searchFieldVariants = cva(
  [
    "inline-flex items-center rounded-sm transition",
    "border border-transparent",
    "bg-input-default",
    "font-sans-plex font-normal",
    "focus-within:outline-none focus-within:ring-2 focus-within:ring-focus focus-within:ring-offset-2 focus-within:ring-offset-focus",
    "hover:border-input-hover",
  ],
  {
    variants: {
      size: {
        md: "h-9 w-55 gap-2 px-2 text-3",
        sm: "h-7 w-50 gap-2 px-2 text-2",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface SearchFieldProps
  extends
    Omit<React.ComponentPropsWithoutRef<"input">, "size" | "type" | "onSubmit">,
    VariantProps<typeof searchFieldVariants> {
  /** Controlled value */
  value?: string;
  /** Default value (uncontrolled) */
  defaultValue?: string;
  /** Callback fired on every keystroke */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /** Callback fired when the user presses Enter */
  onSubmit?: (value: string) => void;
  /** Callback fired when the clear action is triggered */
  onClear?: () => void;
  /** Trailing action slot (Figma: searchOption) — typically IconButton(s) */
  searchOption?: React.ReactNode;
  /** Expand to fill container width */
  fullWidth?: boolean;
  /** Placeholder text */
  placeholder?: string;
  /** Disabled state */
  disabled?: boolean;
  /** Additional CSS classes */
  className?: string;
}

export const SearchField = React.forwardRef<HTMLInputElement, SearchFieldProps>(
  (
    {
      className,
      size,
      value,
      defaultValue,
      onChange,
      onSubmit,
      onClear,
      searchOption,
      fullWidth = false,
      placeholder = "Search\u2026",
      disabled = false,
      ...props
    },
    ref,
  ) => {
    const inputRef = React.useRef<HTMLInputElement>(null);
    const combinedRef = React.useCallback(
      (element: HTMLInputElement | null) => {
        if (typeof ref === "function") ref(element);
        else if (ref) (ref as React.MutableRefObject<HTMLInputElement | null>).current = element;
        inputRef.current = element;
      },
      [ref],
    );

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter" && onSubmit) {
        e.preventDefault();
        onSubmit(inputRef.current?.value ?? "");
      }
      if (e.key === "Escape" && onClear) {
        onClear();
      }
      props.onKeyDown?.(e);
    };

    const handleWrapperClick = (e: React.MouseEvent<HTMLDivElement>) => {
      // Focus the input when clicking the wrapper/icon (not the searchOption slot)
      if ((e.target as HTMLElement).closest("[data-search-option]")) return;
      inputRef.current?.focus();
    };

    return (
      // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
      <div
        role="search"
        aria-label={props["aria-label"] ?? "Search"}
        className={cn(
          searchFieldVariants({ size }),
          disabled && "bg-input-disabled pointer-events-none",
          fullWidth && "w-full",
          "cursor-text",
          className,
        )}
        onClick={handleWrapperClick}
      >
        <Icon
          name="search"
          size={size === "sm" ? 16 : 24}
          aria-hidden={true}
          className={cn("shrink-0", disabled ? "text-input-disabled" : "text-input-placeholder")}
        />
        <input
          ref={combinedRef}
          type="search"
          {...(props["aria-label"] && { "aria-label": props["aria-label"] })}
          {...(value !== undefined ? { value } : { defaultValue })}
          onChange={onChange}
          placeholder={placeholder}
          disabled={disabled}
          className={cn(
            "flex-1 min-w-0 bg-transparent outline-none",
            "placeholder:text-input-placeholder",
            "leading-normal",
            disabled ? "text-input-disabled" : "text-input-placeholder",
            "focus-visible:outline-none",
          )}
          {...props}
          onKeyDown={handleKeyDown}
        />
        {searchOption && (
          <div
            data-search-option
            className="flex items-center shrink-0"
            {...(disabled && { inert: true, "aria-hidden": true })}
          >
            {searchOption}
          </div>
        )}
      </div>
    );
  },
);

SearchField.displayName = "SearchField";

export { searchFieldVariants };
