import { createElement as h } from "react";
import type { ComponentMeta } from "../../types/meta";
import { Button } from "./Button";
import { Icon } from "../icon";

export const ButtonMeta: ComponentMeta = {
  name: "Button",
  description:
    "Primary interaction control for actions such as submit, confirm, cancel, and destructive operations. " +
    "Structured around three axes: variant (default, destructive, ia, highlight), " +
    "priority (primary, secondary, tertiary), and size (sm, md). " +
    "IA and Highlight variants have no primary priority (RULE-04). " +
    "Supports startIcon, endIcon, loading, and fullWidth props.",
  status: "beta",
  version: "0.2.0",
  radixPrimitive: "@radix-ui/react-slot",
  figmaLink:
    "https://www.figma.com/design/0PmhuZzF9XcaIEfMMW2a51/Design_System_2026?node-id=2782-6320",
  figmaNodeId: "2782:6320",
  accessibility: {
    wcag: "2.1 AA",
    wcagStatus: "fail",
    contrastPairs: [
      {
        id: "default primary",
        fg: "--text-negative-primary",
        bg: "--color-filigran-brand-primary",
        minRatio: 4.5,
      },
      {
        id: "default secondary",
        fg: "--color-filigran-brand-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "default tertiary",
        fg: "--color-filigran-brand-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "destructive primary",
        fg: "--text-negative-primary",
        bg: "--color-feedback-error-primary",
        minRatio: 4.5,
      },
      {
        id: "destructive secondary",
        fg: "--color-feedback-error-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "destructive tertiary",
        fg: "--color-feedback-error-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "ia text (stop 1)",
        fg: "--color-filigran-ia-secondary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "ia text (stop 2)",
        fg: "--color-filigran-ia-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "highlight text (stop 1)",
        fg: "--color-filigran-brand-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "highlight text (stop 2)",
        fg: "--color-filigran-tonic-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "focus ring",
        fg: "--color-filigran-brand-primary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
    ],
    notes:
      "Uses native <button> semantics, keyboard accessible, visible focus ring (focus-visible:ring-2). " +
      "Known limitation: highlight gradient stop 2 (--color-filigran-tonic-primary, light mode turquoise-600 #00bd94) " +
      "on --bg-elevation-default (#f2f2f3) = 2.16:1 — fails 4.5:1 AA. Allow-listed until 2026-08-31, " +
      "requires further Figma token remediation. All other declared pairs pass. " +
      "Loading state disables the button and sets aria-busy=true.",
  },
  render() {
    const labelClass =
      "text-content-compact font-content-compact leading-content-compact tracking-content-compact text-default-secondary w-28 shrink-0";
    const sectionClass =
      "text-content-caption font-content-caption leading-content-caption tracking-content-caption text-default-secondary";

    // Valid variant × priority combinations (RULE-04: no primary for ia/highlight)
    const grid: Array<{
      variant: "default" | "destructive" | "ia" | "highlight";
      priorities: Array<"primary" | "secondary" | "tertiary">;
    }> = [
      { variant: "default", priorities: ["primary", "secondary", "tertiary"] },
      {
        variant: "destructive",
        priorities: ["primary", "secondary", "tertiary"],
      },
      { variant: "ia", priorities: ["secondary", "tertiary"] },
      { variant: "highlight", priorities: ["secondary", "tertiary"] },
    ];

    return h(
      "div",
      { className: "flex flex-col gap-6" },

      // Section 1: Variant × Priority grid
      h("p", { className: sectionClass }, "Variant × Priority"),
      h(
        "div",
        { className: "flex flex-col gap-4" },
        // Column headers
        h(
          "div",
          { className: "flex items-center gap-4" },
          h("span", { className: "w-28 shrink-0" }),
          h("span", { className: sectionClass }, "primary"),
          h("span", { className: sectionClass }, "secondary"),
          h("span", { className: sectionClass }, "tertiary"),
        ),
        // Rows
        ...grid.map((row) =>
          h(
            "div",
            {
              key: row.variant,
              className: "flex items-center gap-4 flex-wrap",
            },
            h("span", { className: labelClass }, row.variant),
            ...(["primary", "secondary", "tertiary"] as const).map((priority) =>
              row.priorities.includes(priority)
                ? h(Button, { key: priority, variant: row.variant, priority }, `${row.variant}`)
                : h(
                    "span",
                    {
                      key: priority,
                      className: `${sectionClass} italic`,
                    },
                    "—",
                  ),
            ),
          ),
        ),
      ),

      // Section 2: Sizes
      h("p", { className: sectionClass }, "Sizes"),
      h(
        "div",
        { className: "flex items-center gap-4" },
        h(Button, { size: "sm" }, "Small"),
        h(Button, { size: "md" }, "Medium"),
      ),

      // Section 3: With icons
      h("p", { className: sectionClass }, "With icons"),
      h(
        "div",
        { className: "flex items-center gap-4 flex-wrap" },
        h(Button, { startIcon: h(Icon, { name: "plus", size: 16 }) }, "Start icon"),
        h(Button, { endIcon: h(Icon, { name: "chevron-down", size: 16 }) }, "End icon"),
        h(
          Button,
          {
            priority: "secondary",
            startIcon: h(Icon, { name: "plus", size: 16 }),
          },
          "Add item",
        ),
      ),

      // Section 4: States
      h("p", { className: sectionClass }, "States"),
      h(
        "div",
        { className: "flex items-center gap-4 flex-wrap" },
        h(Button, { disabled: true }, "Disabled primary"),
        h(Button, { priority: "secondary", disabled: true }, "Disabled secondary"),
        h(Button, { priority: "tertiary", disabled: true }, "Disabled tertiary"),
        h(Button, { loading: true }, "Loading"),
      ),

      // Section 5: fullWidth
      h("p", { className: sectionClass }, "Full width"),
      h(Button, { fullWidth: true }, "Full width button"),
    );
  },
  examples: [
    "<Button>Confirm</Button>",
    '<Button priority="secondary" size="sm">Cancel</Button>',
    '<Button variant="destructive" onClick={handleDelete}>Delete report</Button>',
    '<Button variant="destructive" priority="secondary">Remove</Button>',
    '<Button priority="tertiary">More options</Button>',
    '<Button variant="ia" priority="secondary">AI analysis</Button>',
    '<Button variant="highlight" priority="secondary">Highlight action</Button>',
    '<Button startIcon={<Icon name="plus" size={16} />}>Add item</Button>',
    '<Button endIcon={<Icon name="chevron-down" size={16} />}>Options</Button>',
    "<Button loading>Saving...</Button>",
    "<Button fullWidth>Full width action</Button>",
    '// asChild merges Button styles onto the child element (e.g. a router link)\n<Button asChild>\n  <a href="/reports">Open reports</a>\n</Button>',
  ],
  variants: ["default", "destructive", "ia", "highlight"],
  sizes: ["sm", "md"],
  props: {
    variant: '"default" | "destructive" | "ia" | "highlight"',
    priority: '"primary" | "secondary" | "tertiary"',
    size: '"sm" | "md"',
    asChild: "boolean",
    disabled: "boolean",
    startIcon: "ReactNode",
    endIcon: "ReactNode",
    loading: "boolean",
    fullWidth: "boolean",
  },
};
