import * as React from "react";
import { cva } from "class-variance-authority";

import { cn } from "../../lib/cn";
import { Icon } from "../icon";
import { IconButton } from "../icon-button";

const inputVariants = cva(
  [
    // Figma's own resting box uses asymmetric padding (16px/8px) — the 8px
    // right edge is only enough for text, no icon; hasEndSlot widens it.
    "h-9 w-full rounded-sm pl-4 pr-2",
    "bg-input-default text-input-placeholder",
    "font-sans-plex font-normal text-3 leading-normal",
    "placeholder:text-input-placeholder",
    "border transition outline-none",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
    "disabled:bg-input-disabled disabled:text-input-disabled disabled:pointer-events-none",
    // `disabled:text-input-disabled` above only recolors the ELEMENT's own text
    // (the typed value) — `::placeholder` is a separate box that never inherits
    // color from a `:disabled` rule on its host once any rule targets the
    // pseudo-element directly (which line 15's unconditional
    // `placeholder:text-input-placeholder` already does). Without this line the
    // placeholder stayed on `--text-input-placeholder` even while disabled
    // (review: PR #54 round 5). The combined `disabled:placeholder:` variant
    // compiles to a selector requiring BOTH `:disabled` AND `::placeholder`
    // (`.disabled\:placeholder\:text-input-disabled:disabled::placeholder`),
    // which is structurally higher-specificity than the plain
    // `::placeholder`-only rule above — so it wins the cascade deterministically,
    // regardless of Tailwind's internal rule emission order. Proven against the
    // real compiled CSS in scripts/lib/input-disabled-placeholder.test.ts.
    "disabled:placeholder:text-input-disabled",
  ],
  {
    variants: {
      error: {
        true: "border-input-error hover:border-input-error",
        false: "border-transparent hover:border-input-hover",
      },
      hasStartIcon: {
        true: "pl-9",
        false: "",
      },
      hasEndSlot: {
        true: "pr-9",
        false: "",
      },
    },
    defaultVariants: {
      error: false,
      hasStartIcon: false,
      hasEndSlot: false,
    },
  },
);

export interface InputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "size" | "type"
> {
  /** Input type — text field variants only (multiline → Textarea, file → separate) */
  type?: "text" | "password" | "number" | "email";

  /** Controlled value */
  value?: string;
  /** Uncontrolled default value */
  defaultValue?: string;
  /** Change handler (native event passthrough) */
  onChange?: React.ChangeEventHandler<HTMLInputElement>;

  /** Visible label above the field (Figma `hasLabel`). Omit → aria-label or
      aria-labelledby required */
  label?: string;
  /** Marks the field required — renders `*` and sets aria-required (Figma `required`).
      The `*` is label-row anatomy (Figma, RULE-01) — only renders when `label` is
      also set; `aria-required` on the input itself is unaffected either way
      (review: PR #54 round 2) */
  required?: boolean;
  /** Info tooltip trigger shown next to the label (Figma `infosIcon`) */
  infoTooltip?: React.ReactNode;

  /** Placeholder shown when empty (Figma `placeholder`) */
  placeholder?: string;

  /** Helper / description text below the field (Figma `helperText` + `helperContent`) */
  helperText?: React.ReactNode;
  /** Error state — message replaces helperText and switches error tokens.
      String only (arbitration #2 — no boolean; RULE-02) */
  error?: string;
  /** Success state — shows the check-circle indicator (Figma `Success`) */
  success?: boolean;

  /** Character-limit counter (Figma `caraLimit`). When set, shows "N/max" in the
      helper row (RULE-09) and enforces maxLength */
  maxLength?: number;

  /** Single leading decorative icon (arbitration #3 — no Figma precedent, added
      by human arbitration, symmetric to endIcon's decorative branch; RULE-12).
      Always aria-hidden, no interactive variant */
  startIcon?: React.ReactNode;

  /** Single trailing icon slot (Figma `hasEndIcon`). Masked by the state icon in
      error/success (RULE-06). `iconButton` = interactive (password toggle, askAI,
      attach, clear) and composes the FDS <IconButton> (`label` is its required
      accessible name); `icon` = decorative only, always aria-hidden — no `label`
      field, it would never be read (review: PR #54 round 1) */
  endIcon?:
    | {
        type: "iconButton";
        icon: React.ReactNode;
        // Matches IconButtonProps's real onClick type (React.ComponentPropsWithoutRef<"button">,
        // i.e. React.MouseEventHandler<HTMLButtonElement>) instead of a bare `() => void`.
        // A 0-arg signature technically "worked" (Input never reads the event itself,
        // and TS allows passing a 0-arg fn wherever a 1-arg handler is expected) but
        // incorrectly REJECTED any consumer handler that reads the event, e.g.
        // `(event) => { event.stopPropagation(); ... }` (review: PR #54 round 5).
        onClick: React.MouseEventHandler<HTMLButtonElement>;
        label: string;
      }
    | { type: "icon"; icon: React.ReactNode };

  /** Disables the field (Figma `Disabled`) */
  disabled?: boolean;

  className?: string;
}

// Component is wrapped in React.forwardRef<HTMLInputElement, InputProps> — the
// ref attaches directly to the native <input>, no wrapper div (arbitration #1,
// RULE-11). ref connects straight through: no internal combinedRef is needed
// since, unlike SearchField, Input has no imperative read of its own.
export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      id,
      type = "text",
      value,
      defaultValue,
      onChange,
      label,
      required = false,
      infoTooltip,
      placeholder,
      helperText,
      error,
      success = false,
      maxLength,
      startIcon,
      endIcon,
      disabled = false,
      ...props
    },
    ref,
  ) => {
    const generatedId = React.useId();
    const inputId = id ?? generatedId;
    const helperId = `${inputId}-helper`;

    // Prop contract violation (documented above: "Omit label → aria-label
    // required") — dev-only diagnostic per AGENTS.md "Prop contract
    // violations": warn, never throw. Same shape as Dialog's missing-
    // DialogTitle check (`Dialog.tsx`) — an unlabeled control still renders
    // and functions, it just has no accessible name (review: PR #54 round 1).
    // aria-labelledby is an equally valid accessible-name source (WAI-ARIA) —
    // must not false-positive when a consumer uses it instead of aria-label
    // (review: PR #54 round 3).
    if (
      typeof process !== "undefined" &&
      process.env.NODE_ENV !== "production" &&
      !label &&
      !props["aria-label"] &&
      !props["aria-labelledby"]
    ) {
      console.warn(
        "[Input] rendered without a `label` prop, an `aria-label`, or an " +
          "`aria-labelledby`. The field will still render and function, but " +
          "has no accessible name (WCAG 1.3.1, 4.1.2). Add a visible `label`, " +
          "an `aria-label`, or an `aria-labelledby`.",
      );
    }

    // Display-only character count (RULE-09). Native `maxLength` enforces
    // truncation at the DOM level for user *typing* only — it does not clamp
    // a controlled `value` set programmatically (a parent can still pass a
    // string longer than `maxLength` and it renders in full); this only
    // tracks the number shown in "N/max", it doesn't enforce it.
    const [uncontrolledLength, setUncontrolledLength] = React.useState(
      () => (defaultValue ?? "").length,
    );
    const isControlled = value !== undefined;
    const currentLength = isControlled ? value.length : uncontrolledLength;

    const handleChange: React.ChangeEventHandler<HTMLInputElement> = (event) => {
      if (!isControlled) setUncontrolledLength(event.target.value.length);
      onChange?.(event);
    };

    // Error masks success (RULE-06 precedence — a field is never both at once
    // visually, error is the more urgent condition).
    const showErrorIcon = Boolean(error);
    const showSuccessIcon = success && !showErrorIcon;
    const hasStateIcon = showErrorIcon || showSuccessIcon;
    const hasEndSlot = hasStateIcon || Boolean(endIcon);

    // Label, the required "*" marker, and helper/counter text all share one
    // tone-precedence rule: disabled > error > default (Figma's own "*" glyph
    // turns text-input-error in the Error state, verified via live extraction —
    // the RFC's §3.4 table text was corrected to match). The ternary is
    // duplicated inline at each usage site below (rather than hoisted to a
    // shared `const`) because scripts/lib/tsx-classnames.ts's AST-based
    // check-figma-fidelity.ts scoping only traces string literals passed
    // directly to cn()/className, not through an intermediate variable
    // reference — see that file's module comment.

    const helperMessage = error ?? helperText;
    const showHelperRow = Boolean(helperMessage) || maxLength !== undefined;

    // aria-describedby is merged, never overridden, with any consumer-provided
    // value (WAI-ARIA accepts a space-separated ID list) — a consumer's own
    // description must survive alongside the internal helper/error link.
    // aria-invalid/aria-required stay component-managed and always win instead
    // (booleans reflecting actual field state, not a combinable list): both are
    // set after `{...props}` below so they can't be silently clobbered by a
    // same-named prop (review: PR #54 round 3).
    const mergedDescribedBy = showHelperRow
      ? [props["aria-describedby"], helperId].filter(Boolean).join(" ")
      : props["aria-describedby"];

    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        {label && (
          <div className="flex items-center gap-1">
            <label
              htmlFor={inputId}
              className={cn(
                "font-sans-plex font-medium text-2",
                disabled ? "text-input-disabled" : error ? "text-input-error" : "text-input-label",
              )}
            >
              {label}
            </label>
            {required && (
              <span
                aria-hidden="true"
                className={cn(
                  "font-sans-plex font-normal text-3",
                  disabled
                    ? "text-input-disabled"
                    : error
                      ? "text-input-error"
                      : "text-input-required",
                )}
              >
                *
              </span>
            )}
            {infoTooltip && <span className="inline-flex items-center">{infoTooltip}</span>}
          </div>
        )}

        <div className="relative w-full">
          {startIcon && (
            <span
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute inset-y-0 left-0 flex items-center pl-4",
                disabled ? "text-input-disabled" : "text-input-placeholder",
              )}
            >
              {startIcon}
            </span>
          )}

          <input
            ref={ref}
            id={inputId}
            type={type}
            {...(value !== undefined ? { value } : { defaultValue })}
            onChange={handleChange}
            placeholder={placeholder}
            disabled={disabled}
            required={required}
            maxLength={maxLength}
            className={inputVariants({
              error: showErrorIcon,
              hasStartIcon: Boolean(startIcon),
              hasEndSlot,
            })}
            {...props}
            aria-required={required || undefined}
            aria-invalid={showErrorIcon || undefined}
            aria-describedby={mergedDescribedBy || undefined}
          />

          {showErrorIcon && (
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-4 text-input-error"
            >
              <Icon name="circle-alert" size={16} aria-hidden={true} />
            </span>
          )}
          {showSuccessIcon && (
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-4 text-feedback-success-primary"
            >
              <Icon name="circle-check" size={16} aria-hidden={true} />
            </span>
          )}
          {!hasStateIcon && endIcon && endIcon.type === "iconButton" && (
            <span className="absolute inset-y-0 right-0 flex items-center pr-2">
              <IconButton
                icon={endIcon.icon}
                aria-label={endIcon.label}
                onClick={endIcon.onClick}
                disabled={disabled}
                variant="default"
                priority="tertiary"
                size="sm"
              />
            </span>
          )}
          {!hasStateIcon && endIcon && endIcon.type === "icon" && (
            <span
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute inset-y-0 right-0 flex items-center pr-2",
                disabled ? "text-input-disabled" : "text-input-placeholder",
              )}
            >
              {endIcon.icon}
            </span>
          )}
        </div>

        {showHelperRow && (
          <div id={helperId} className="flex items-start justify-between gap-2">
            {helperMessage && (
              <span
                className={cn(
                  "font-sans-plex font-normal text-1",
                  disabled
                    ? "text-input-disabled"
                    : error
                      ? "text-input-error"
                      : "text-input-helper",
                )}
              >
                {helperMessage}
              </span>
            )}
            {maxLength !== undefined && (
              <span
                className={cn(
                  "font-sans-plex font-normal text-1 shrink-0",
                  disabled
                    ? "text-input-disabled"
                    : error
                      ? "text-input-error"
                      : "text-input-helper",
                )}
              >
                {currentLength}/{maxLength}
              </span>
            )}
          </div>
        )}
      </div>
    );
  },
);

Input.displayName = "Input";

export { inputVariants };
