import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../../lib/cn";

const iconButtonVariants = cva(
  [
    "inline-flex items-center justify-center",
    "rounded-sm transition",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
    "disabled:pointer-events-none",
  ],
  {
    variants: {
      variant: {
        default: "focus-visible:ring-filigran-brand-primary",
        destructive: "focus-visible:ring-feedback-error-primary",
        ia: "focus-visible:ring-filigran-ia-secondary",
      },
      priority: {
        primary: "disabled:bg-elevation-disabled disabled:text-default-disabled",
        secondary: ["border", "disabled:text-default-disabled disabled:border-current"],
        tertiary: "disabled:text-default-disabled",
      },
      size: {
        sm: "h-6 w-6",
        md: "h-9 w-9",
      },
    },
    compoundVariants: [
      // default × primary
      {
        variant: "default",
        priority: "primary",
        className:
          "bg-filigran-brand-primary text-negative-primary hover:bg-filigran-brand-tertiary active:bg-filigran-brand-tertiary",
      },
      // default × secondary
      {
        variant: "default",
        priority: "secondary",
        className:
          "border-elevation-default text-filigran-brand-primary hover:bg-filigran-brand-primary-transparency active:bg-filigran-brand-primary-transparency",
      },
      // default × tertiary
      {
        variant: "default",
        priority: "tertiary",
        className:
          "text-filigran-brand-primary hover:bg-filigran-brand-primary-transparency active:bg-filigran-brand-primary-transparency",
      },
      // destructive × primary
      {
        variant: "destructive",
        priority: "primary",
        className:
          "bg-feedback-error-primary text-negative-primary hover:bg-feedback-error-secondary active:bg-feedback-error-secondary",
      },
      // destructive × secondary
      {
        variant: "destructive",
        priority: "secondary",
        className:
          "border-feedback-error-secondary text-feedback-error-primary hover:bg-feedback-error-secondary-transparency active:bg-feedback-error-secondary-transparency",
      },
      // destructive × tertiary
      {
        variant: "destructive",
        priority: "tertiary",
        className:
          "text-feedback-error-primary hover:bg-feedback-error-secondary-transparency active:bg-feedback-error-secondary-transparency",
      },
      // ia × secondary — gradient border
      {
        variant: "ia",
        priority: "secondary",
        className:
          "border-transparent hover:bg-filigran-ia-secondary-transparency active:bg-filigran-ia-secondary-transparency",
      },
      // ia × tertiary
      {
        variant: "ia",
        priority: "tertiary",
        className:
          "hover:bg-filigran-ia-secondary-transparency active:bg-filigran-ia-secondary-transparency",
      },
    ],
    defaultVariants: {
      variant: "default",
      priority: "primary",
      size: "md",
    },
  },
);

export interface IconButtonProps
  extends
    Omit<React.ComponentPropsWithoutRef<"button">, "children" | "aria-label">,
    VariantProps<typeof iconButtonVariants> {
  /** The icon element to render — must be aria-hidden (the button itself carries the accessible label) */
  icon: React.ReactNode;
  /** Required accessible label — icon-only buttons have no visible text */
  "aria-label": string;
  /** Active state (e.g. toggle is on) */
  active?: boolean;
}

export const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, priority, size, icon, active, type = "button", ...props }, ref) => {
    const resolvedVariant = variant ?? "default";
    const resolvedPriority = priority ?? "primary";
    // IA has no primary — coerce to secondary
    const enforcedPriority =
      resolvedVariant === "ia" && resolvedPriority === "primary" ? "secondary" : resolvedPriority;

    const isGradientType = resolvedVariant === "ia";
    const isGradientBorder = isGradientType && enforcedPriority === "secondary" && !props.disabled;

    return (
      <button
        className={cn(
          iconButtonVariants({ variant, priority: enforcedPriority, size }),
          isGradientBorder && "gradient-border-ia",
          active &&
            (resolvedVariant === "destructive"
              ? "bg-feedback-error-secondary-transparency"
              : resolvedVariant === "ia"
                ? "bg-filigran-ia-secondary-transparency"
                : "bg-filigran-brand-primary-transparency"),
          className,
        )}
        ref={ref}
        type={type}
        {...(active !== undefined && { "aria-pressed": active })}
        {...props}
      >
        <span className="inline-flex shrink-0" aria-hidden="true">
          {icon}
        </span>
      </button>
    );
  },
);

IconButton.displayName = "IconButton";

export { iconButtonVariants };
