import React, { createElement as h } from "react";
import type { ComponentMeta } from "../../types/meta";
import { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider } from "./Tooltip";
import { Icon } from "../icon";

export const TooltipMeta: ComponentMeta = {
  name: "Tooltip",
  description:
    "Contextual popup that displays informational text when a trigger element is hovered or focused. Built on @radix-ui/react-tooltip for accessible behavior (delay, dismiss on Escape, screen reader announcements). Compound component: wrap content in TooltipProvider > Tooltip > TooltipTrigger + TooltipContent.",
  status: "stable",
  version: "0.1.0",
  radixPrimitive: "@radix-ui/react-tooltip",
  figmaLink:
    "https://www.figma.com/design/0PmhuZzF9XcaIEfMMW2a51/Design_System_2026?node-id=2777-2937&t=tG8r0rUXodx8CTLs-1",
  figmaNodeId: "2777:2937",
  examples: [
    `<TooltipProvider>
  <Tooltip>
    <TooltipTrigger>Hover me</TooltipTrigger>
    <TooltipContent>
      Lorem ipsum dolor sit amet
    </TooltipContent>
  </Tooltip>
</TooltipProvider>`,
    `<TooltipProvider>
  <Tooltip>
    <TooltipTrigger asChild>
      <button>Action</button>
    </TooltipTrigger>
    <TooltipContent side="right">
      Lorem ipsum dolor sit amet
    </TooltipContent>
  </Tooltip>
</TooltipProvider>`,
  ],
  variants: ["default"],
  sizes: [],
  props: {
    "TooltipContent.content":
      "ReactNode — Content displayed inside the tooltip popup (children of TooltipContent)",
    "TooltipContent.side":
      '"top" | "right" | "bottom" | "left" — Preferred side of the trigger (default: "top")',
    "TooltipContent.sideOffset": "number — Distance in px between trigger and tooltip (default: 8)",
    "TooltipProvider.delayDuration":
      "number — Ms from pointer enter until tooltip opens (default: 700, set on TooltipProvider)",
  },
  render() {
    const triggerClass =
      "inline-flex items-center justify-center rounded-md border border-elevation-default " +
      "px-4 py-2 text-content-compact font-content-compact leading-content-compact " +
      "tracking-content-compact text-default-primary " +
      "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus";

    const labelClass =
      "text-content-caption font-content-caption leading-content-caption " +
      "tracking-content-caption text-default-secondary";

    // Icon trigger demo using the shared Icon component
    const questionIcon = h(Icon, {
      name: "circle-question-mark",
      size: 16,
      "aria-hidden": true,
    } as React.ComponentProps<typeof Icon>);

    return h(
      TooltipProvider as React.FC<{ delayDuration?: number; children: React.ReactNode }>,
      { delayDuration: 0 } as { delayDuration: number; children: React.ReactNode },
      h(
        "div",
        { className: "flex flex-col gap-6 py-4" },
        // Row 1: Placements
        h(
          "div",
          { className: "flex flex-col gap-2" },
          h("span", { className: labelClass }, "Placements"),
          h(
            "div",
            { className: "flex items-center gap-6 py-4" },
            h(
              Tooltip,
              null,
              h(TooltipTrigger, { className: triggerClass }, "Left"),
              h(TooltipContent, { side: "left" }, "Left placement"),
            ),
            h(
              Tooltip,
              null,
              h(TooltipTrigger, { className: triggerClass }, "Top"),
              h(TooltipContent, { side: "top" }, "Top placement"),
            ),
            h(
              Tooltip,
              null,
              h(TooltipTrigger, { className: triggerClass }, "Bottom"),
              h(TooltipContent, { side: "bottom" }, "Bottom placement"),
            ),
            h(
              Tooltip,
              null,
              h(TooltipTrigger, { className: triggerClass }, "Right"),
              h(TooltipContent, { side: "right" }, "Right placement"),
            ),
          ),
        ),
        // Row 2: Icon trigger (no visible label)
        h(
          "div",
          { className: "flex flex-col gap-2" },
          h("span", { className: labelClass }, "Icon trigger (no visible label)"),
          h(
            "div",
            { className: "flex items-center gap-4 py-4" },
            h(
              Tooltip,
              null,
              h(
                TooltipTrigger,
                {
                  asChild: true,
                },
                h(
                  "button",
                  {
                    type: "button",
                    "aria-label": "API token details",
                    className:
                      "inline-flex items-center justify-center rounded-md p-2 text-default-primary " +
                      "hover:bg-elevation-highlight " +
                      "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
                  },
                  questionIcon,
                ),
              ),
              h(TooltipContent, { side: "right" }, "Show API token details"),
            ),
          ),
        ),
        // Row 3: Jargon definition
        h(
          "div",
          { className: "flex flex-col gap-2" },
          h("span", { className: labelClass }, "Jargon definition"),
          h(
            "div",
            { className: "flex items-center gap-4 py-4" },
            h(
              Tooltip,
              null,
              h(
                TooltipTrigger,
                { asChild: true },
                h(
                  "span",
                  {
                    tabIndex: 0,
                    className:
                      "text-content-compact font-content-compact leading-content-compact " +
                      "tracking-content-compact text-default-primary " +
                      "border-b border-dashed border-elevation-default cursor-help " +
                      "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
                  },
                  "TLP",
                ),
              ),
              h(
                TooltipContent,
                { side: "top" },
                "TLP indicates sharing restrictions for this intelligence.",
              ),
            ),
          ),
        ),
        // Row 4: Truncated text
        h(
          "div",
          { className: "flex flex-col gap-2" },
          h("span", { className: labelClass }, "Truncated text with full content"),
          h(
            "div",
            { className: "flex items-center gap-4 py-4" },
            h(
              Tooltip,
              null,
              h(
                TooltipTrigger,
                { asChild: true },
                h(
                  "span",
                  {
                    tabIndex: 0,
                    className:
                      "truncate max-w-45 inline-block text-content-compact font-content-compact " +
                      "leading-content-compact tracking-content-compact text-default-primary " +
                      "focus-visible:outline-none focus-visible:ring-2 ring-focus focus-visible:ring-offset-2 focus-visible:ring-offset-focus",
                  },
                  "This is the complete value for the truncated cell content.",
                ),
              ),
              h(
                TooltipContent,
                { side: "top" },
                "This is the complete value for the truncated cell content.",
              ),
            ),
          ),
        ),
      ),
    );
  },
  accessibility: {
    wcag: "2.1 AA",
    wcagStatus: "pass",
    contrastPairs: [
      {
        id: "content",
        fg: "--text-default-primary",
        bg: "--border-elevation-subtle",
        minRatio: 4.5,
      },
    ],
    notes:
      "content dark: --text-default-primary (gray-100 #f2f2f3) on --border-elevation-subtle (grayblue-500 #1f3965) = 8.6:1 ✅\n" +
      "content light: --text-default-primary (gray-900 #18191b) on --border-elevation-subtle (gray-200 #cacbce) = 10.2:1 ✅\n" +
      "Keyboard: tooltip opens on trigger focus, closes on Escape. Role=tooltip with aria-describedby on the trigger (handled by Radix).",
  },
};
