    "TabsTrigger.icon":
      "ReactNode — optional 16×16 leading icon (decorative, aria-hidden). Ignored when asChild is true.",
    "TabsTrigger.badge":
      "number | string — optional count badge displayed next to the label. Ignored when asChild is true.",
    "TabsTrigger.badgeColor":
      '"brand" | "error" — semantic color variant for the badge (default: "brand", visually identical to the pre-existing badge). Purely decorative — never implies interactivity or clickability. Ignored when asChild is true or badge is undefined.',
    "TabsTrigger.badgeMax":
      'number — caps a numeric badge: values greater than badgeMax render as "${badgeMax}+" (e.g. badge={150} badgeMax={99} → "99+"). No default (uncapped) — ignored for string badges and when asChild is true. A negative or non-finite badgeMax (e.g. -1, NaN, Infinity) is treated as uncapped rather than applied literally.',
