import React, { createElement as h } from "react";
import type { ComponentMeta } from "../../types/meta";
import { IconButton } from "./IconButton";
import { Icon } from "../icon";
import type { IconName } from "../icon";

export const IconButtonMeta: ComponentMeta = {
  name: "IconButton",
  description:
    "Square button that renders a single icon with no text label. Requires an accessible aria-label. Shares the variant × priority × size pattern with Button. Use for toolbar actions, close/dismiss, and any action where the icon alone is sufficient context (pair with Tooltip for disambiguation).",
  status: "stable",
  version: "0.1.0",
  radixPrimitive: "none",
  figmaLink:
    "https://www.figma.com/design/0PmhuZzF9XcaIEfMMW2a51/Design_System_2026?node-id=2785-15267&t=tG8r0rUXodx8CTLs-1",
  figmaNodeId: "2785:15267",
  examples: [
    `<IconButton icon={<Icon name="plus" />} aria-label="Add item" />`,
    `<IconButton variant="destructive" priority="secondary" icon={<Icon name="trash-2" />} aria-label="Delete" />`,
    `<IconButton variant="ia" priority="secondary" icon={<Icon name="bot" gradient="ia" />} aria-label="AI assist" />`,
    `<IconButton size="sm" priority="tertiary" icon={<Icon name="x" />} aria-label="Close" />`,
  ],
  variants: ["default", "destructive", "ia"],
  sizes: ["sm", "md"],
  props: {
    icon: "ReactNode — The icon element to render (must be aria-hidden; the button carries the accessible label)",
    variant: '"default" | "destructive" | "ia" — Visual intent (default: "default")',
    priority: '"primary" | "secondary" | "tertiary" — Visual weight (default: "primary")',
    size: '"sm" | "md" — Size: sm=24px, md=36px (default: "md")',
    active: "boolean — Active/toggle-on state (default: false)",
    "aria-label": "string — Required accessible label (no visible text)",
  },
  render() {
    const iconEl = (name: IconName) => h(Icon, { name, size: 24 });
    const iconIaEl = (name: IconName) => h(Icon, { name, size: 24, gradient: "ia" });
    const iconSmEl = (name: IconName) => h(Icon, { name, size: 16 });

    const labelClass =
      "text-content-caption font-content-caption leading-content-caption " +
      "tracking-content-caption text-default-secondary";

    return h(
      "div",
      { className: "flex flex-col gap-6" },
      // Priority: Primary
      h(
        "div",
        { className: "flex flex-col gap-2" },
        h("span", { className: labelClass }, "Primary"),
        h(
          "div",
          { className: "flex items-center gap-4" },
          h(IconButton, {
            variant: "default",
            priority: "primary",
            icon: iconEl("plus"),
            "aria-label": "Add",
          }),
          h(IconButton, {
            variant: "default",
            priority: "primary",
            icon: iconEl("plus"),
            "aria-label": "Add (disabled)",
            disabled: true,
          }),
        ),
      ),
      // Priority: Secondary
      h(
        "div",
        { className: "flex flex-col gap-2" },
        h("span", { className: labelClass }, "Secondary"),
        h(
          "div",
          { className: "flex items-center gap-4" },
          h(IconButton, {
            variant: "default",
            priority: "secondary",
            icon: iconEl("pencil"),
            "aria-label": "Edit",
          }),
          h(IconButton, {
            variant: "destructive",
            priority: "secondary",
            icon: iconEl("trash-2"),
            "aria-label": "Delete",
          }),
          h(IconButton, {
            variant: "ia",
            priority: "secondary",
            icon: iconIaEl("bot"),
            "aria-label": "AI",
          }),
        ),
      ),
      // Priority: Tertiary
      h(
        "div",
        { className: "flex flex-col gap-2" },
        h("span", { className: labelClass }, "Tertiary"),
        h(
          "div",
          { className: "flex items-center gap-4" },
          h(IconButton, {
            variant: "default",
            priority: "tertiary",
            icon: iconEl("ellipsis-vertical"),
            "aria-label": "More",
          }),
          h(IconButton, {
            variant: "destructive",
            priority: "tertiary",
            icon: iconEl("trash-2"),
            "aria-label": "Delete",
          }),
          h(IconButton, {
            variant: "ia",
            priority: "tertiary",
            icon: iconIaEl("bot"),
            "aria-label": "AI",
          }),
        ),
      ),
      // Size: sm
      h(
        "div",
        { className: "flex flex-col gap-2" },
        h("span", { className: labelClass }, "Small (sm)"),
        h(
          "div",
          { className: "flex items-center gap-4" },
          h(IconButton, {
            size: "sm",
            variant: "default",
            priority: "primary",
            icon: iconSmEl("plus"),
            "aria-label": "Add",
          }),
          h(IconButton, {
            size: "sm",
            variant: "default",
            priority: "secondary",
            icon: iconSmEl("pencil"),
            "aria-label": "Edit",
          }),
          h(IconButton, {
            size: "sm",
            variant: "default",
            priority: "tertiary",
            icon: iconSmEl("x"),
            "aria-label": "Close",
          }),
        ),
      ),
      // Disabled state
      h(
        "div",
        { className: "flex flex-col gap-2" },
        h("span", { className: labelClass }, "Disabled"),
        h(
          "div",
          { className: "flex items-center gap-4" },
          h(IconButton, {
            variant: "default",
            priority: "primary",
            disabled: true,
            icon: iconEl("bookmark"),
            "aria-label": "Pinned (disabled)",
          }),
          h(IconButton, {
            variant: "default",
            priority: "secondary",
            disabled: true,
            icon: iconEl("bookmark"),
            "aria-label": "Pinned (disabled)",
          }),
          h(IconButton, {
            variant: "default",
            priority: "tertiary",
            disabled: true,
            icon: iconEl("bookmark"),
            "aria-label": "Pinned (disabled)",
          }),
        ),
      ),
    );
  },
  accessibility: {
    wcag: "2.1 AA",
    wcagStatus: "pass",
    contrastPairs: [
      {
        id: "primary-icon",
        fg: "--text-negative-primary",
        bg: "--color-filigran-brand-primary",
        minRatio: 4.5,
      },
      {
        id: "secondary-icon",
        fg: "--color-filigran-brand-primary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
      {
        id: "destructive-icon",
        fg: "--color-feedback-error-primary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
      {
        id: "focus ring",
        fg: "--color-filigran-brand-primary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
    ],
    notes:
      "primary dark: --text-negative-primary (#18191b) on --color-filigran-brand-primary (blue-500 #0fbcff) = 8.0:1 ✅\n" +
      "primary light: --text-negative-primary (#f2f2f3) on --color-filigran-brand-primary (darkblue-700 #0015a8) = 11.2:1 ✅\n" +
      "secondary icon dark: --color-filigran-brand-primary (#0fbcff) on grayblue-1000 (#070d18) = 9.2:1 ✅\n" +
      "Keyboard: standard button focus ring. aria-label required (no visible text).",
  },
};
