import { createElement as h } from "react";
import type { ComponentMeta } from "../../types/meta";
import { Text, type TextVariant } from "./Text";

export const TextMeta: ComponentMeta = {
  name: "Text",
  description:
    'The design system\'s typography primitive. Renders any of the 19 arbitrated Named Styles (process/TYPO-MAPPING.md, theme.css) while deliberately decoupling the HTML tag from the visual style: `as` picks the semantic element (h1, p, span, label, a...), `variant` picks the Named Style — never both at once. Also the primary migration vehicle for MUI <Typography variant="X"> usage across products (see Text.rfc.md §4.4 for the full crosswalk).',
  status: "stable",
  version: "0.1.0",
  radixPrimitive: "none",
  figmaLink:
    "https://www.figma.com/design/0PmhuZzF9XcaIEfMMW2a51/Design_System_2026?node-id=2671-1684",
  figmaNodeId: "2671:1684",
  variants: [
    "title-2xl",
    "title-xl",
    "title-lg",
    "title-md",
    "title-sm",
    "title-xs",
    "title-jumbo",
    "content-base",
    "content-base-bold",
    "content-base-medium",
    "content-base-link",
    "content-compact",
    "content-compact-bold",
    "content-compact-medium",
    "content-compact-link",
    "content-caption",
    "content-highlight",
    "content-button",
    "content-code",
  ],
  sizes: [],
  examples: [
    '// Section title — as defaults to h3 for title-lg\n<Text variant="title-lg">Threat overview</Text>',
    '// Same visual style, different semantics — as/variant never merge\n<Text as="div" variant="title-lg">Card header, not a heading</Text>',
    '// Standard body paragraph (as defaults to p)\n<Text variant="content-base">Lorem ipsum dolor sit amet.</Text>',
    '// Inline link — as defaults to a; underline + focus ring included in the variant\n<Text as="a" href="/reports" variant="content-base-link">\n  View full report\n</Text>',
    '// className is the sole styling escape hatch (color, spacing, alignment...)\n<Text variant="content-compact" className="text-default-secondary">\n  Last updated 2 minutes ago\n</Text>',
    '// MUI migration — variant="h3" component="div" becomes:\n<Text as="div" variant="title-lg">Widget title</Text>',
  ],
  render() {
    const label = (text: string) =>
      h(
        "p",
        {
          className:
            "text-content-caption font-content-caption leading-content-caption tracking-content-caption text-default-secondary",
        },
        text,
      );
    const stack = (children: ReturnType<typeof h>[]) =>
      h("div", { className: "flex flex-col gap-3" }, ...children);
    const sample = (variant: TextVariant, text: string) =>
      h(Text, { key: variant, variant, children: text });
    // The two `-link` variants default `as` to `a` (TEXT_DEFAULT_TAG) but an
    // `<a>` with no `href` isn't part of the tab order and has no link
    // semantics in the accessibility tree — it would render as inert,
    // non-focusable text, contradicting the "navigable"/focus-ring framing
    // of this showcase. A real `href` here exercises the actual contract
    // (RFC §4.1/§6.3: focus-ring is only ever active when the consumer
    // supplies `href` or overrides `as`).
    const linkSample = (variant: TextVariant, text: string) =>
      h(Text, { key: variant, variant, as: "a", href: "#", children: text });

    return h(
      "div",
      { className: "flex flex-col gap-8" },
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Titles — heading ladder (as defaults to h1\u2013h6)"),
        stack([
          sample("title-2xl", "Title 2XL — page title (h1)"),
          sample("title-xl", "Title XL (h2)"),
          sample("title-lg", "Title LG (h3)"),
          sample("title-md", "Title MD (h4)"),
          sample("title-sm", "Title SM (h5)"),
          sample("title-xs", "Title XS (h6)"),
        ]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Title jumbo — KPI/counter display (as defaults to p, not a heading)"),
        stack([sample("title-jumbo", "1 284")]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Content — base (14px) and compact (12px), weight variants"),
        stack([
          sample("content-base", "Content base — regular body text (p)"),
          sample("content-base-medium", "Content base medium"),
          sample("content-base-bold", "Content base bold"),
          sample("content-compact", "Content compact — secondary/dense body text (p)"),
          sample("content-compact-medium", "Content compact medium"),
          sample("content-compact-bold", "Content compact bold"),
        ]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Content — links (underline + focus ring, as defaults to a)"),
        stack([
          linkSample("content-base-link", "Content base link — inline navigable text"),
          linkSample("content-compact-link", "Content compact link"),
        ]),
      ),
      h(
        "div",
        { className: "flex flex-col gap-2" },
        label("Content — caption, highlight, button, code"),
        stack([
          sample("content-caption", "Content caption — annotation/legend text (span)"),
          sample("content-highlight", "Content highlight — emphasized lead text (p)"),
          sample("content-button", "Content button — reserved for the Button component (span)"),
          sample("content-code", "Content code — inline code sample (code)"),
        ]),
      ),
    );
  },
  props: {
    as: 'React.ElementType (optional) — the native HTML tag to render (e.g. "h1", "p", "span", "label", "a"). Purely semantic, never affects the visual style. Defaults to a sensible tag per variant when omitted (TEXT_DEFAULT_TAG export; full rationale table in Text.rfc.md §4.1).',
    variant:
      "TextVariant (required) — the Named Style to apply, sourced from theme.css / process/TYPO-MAPPING.md. No implicit default: MUI's own silent body1 default was found to cause ambiguity in 11% of real usages (Text.rfc.md §2.4).",
    className:
      "string (optional) — extra classes merged via tailwind-merge. The sole styling escape hatch in v1 scope: color, alignment, truncation, spacing all flow through here instead of dedicated props (Text.rfc.md §7 Out of scope).",
    children: "React.ReactNode (required) — the text content.",
  },
  accessibility: {
    wcag: "2.1 AA",
    wcagStatus: "pass",
    contrastPairs: [
      {
        id: "body text (primary) on default elevation",
        fg: "--text-default-primary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "secondary body text on default elevation",
        fg: "--text-default-secondary",
        bg: "--bg-elevation-default",
        minRatio: 4.5,
      },
      {
        id: "large heading (primary) on default elevation",
        fg: "--text-default-primary",
        bg: "--bg-elevation-default",
        minRatio: 3,
      },
    ],
    notes:
      "Criteria: 1.3.1 Info and Relationships — `as` renders the real native element (h1\u2013h6, p, span, label, a, code) with no ARIA role substitution, so the document outline and text semantics are exactly what the markup says; `variant` never influences this (Text.rfc.md \u00abArbitrage\u00bb). " +
      "1.4.3 Contrast (Minimum) — Text sets no default color of its own by design; color flows through className, chosen per usage. The pairs above document the common/recommended token combinations exercised in render(): normal-size content-* variants at 4.5:1, and large (\u226524px) title-2xl/xl/lg headings at the WCAG large-text allowance of 3:1. " +
      "2.4.7 Focus Visible / 2.1.1 Keyboard — Text adds no keyboard handling of its own. The two link variants (content-base-link, content-compact-link) default to <a> and include the standard focus-ring utility classes, active whenever the consumer supplies href (or overrides as to another focusable element); all other variants are static, non-interactive text with no focus behaviour. " +
      "wcagStatus 'pass' basis: axe-core conformity suite reports 0 violations across every variant in both modes (render() surface), and all three declared contrast pairs are computed from tokens in CI (pnpm check:contrast) rather than hand-entered. Automated checks cover roughly half of WCAG — human/screen-reader audit cadence still applies per release.",
  },
};
