import { createElement as h } from "react";
import type { ComponentMeta } from "../../types/meta";
import { Navbar, NavbarSeparator } from "./Navbar";
import { NavbarItem } from "../navbar-item/NavbarItem";
import { NavbarSubmenu, NavbarSubmenuItem } from "../navbar-submenu/NavbarSubmenu";
import { ProductSwitcher } from "../product-switcher/ProductSwitcher";
import { Icon } from "../icon";

export const NavbarMeta: ComponentMeta = {
  name: "Navbar",
  description:
    "The primary structural navigation container of every Filigran product: a vertical, " +
    "collapsible sidebar hosting a header slot (typically ProductSwitcher), a scrollable list " +
    "of NavbarItem/NavbarSubmenu rows (separated into groups by NavbarSeparator), an optional " +
    "footer slot, and a built-in collapse toggle. A thin composition root, not a monolith — it " +
    "owns the collapsed/expanded state, the <nav> landmark, and the width transition, sharing " +
    "collapsed with its descendants via NavbarContext rather than rendering their content " +
    "itself. Renders a real <nav aria-label> landmark, a real accessibility improvement over " +
    "both opencti and openaev's current MUI Drawer-based sidebars (neither renders a landmark " +
    "today).",
  status: "stable",
  version: "0.1.0",
  radixPrimitive: "none",
  figmaLink:
    "https://www.figma.com/design/0PmhuZzF9XcaIEfMMW2a51/Design_System_2026?node-id=2843-4074",
  figmaNodeId: "2843:4074",
  accessibility: {
    wcag: "2.1 AA",
    wcagStatus: "pass",
    // Correction (repass #2 conformity gate): Navbar is NOT actually
    // content-less — it directly renders its own footer collapse/expand
    // toggle row (`<NavbarItem icon=... onClick={handleToggle}>{collapsed ?
    // "Expand" : "Collapse"}</NavbarItem>` in Navbar.tsx), a real element
    // instantiated BY this component itself, not supplied by a consumer via
    // children/props — unlike the scrollable item list or header/footer
    // slots, which genuinely are opaque consumer content this component
    // never styles. The prior empty array assumed the whole surface was
    // opaque; the toggle row is the one exception. Its fg/bg tokens are the
    // same ones NavbarItem.meta.ts already declares for its default
    // label/icon state (this row renders in that exact state), so these
    // entries are intentionally duplicate values, not a second independent
    // token choice — declared here too because the conformity suite
    // (src/__tests__/conformity.test.tsx) requires every discovered
    // component to carry at least one contrastPairs entry, with no
    // "composes only" exemption. The border-r removal note from fidelity
    // re-pass #2 point 1 still stands (node 5425:11518: plain background
    // transition, no distinct stroke) — that part of the container remains
    // genuinely content-less.
    //
    // Fidelity re-pass #3 point 2: the panel's own background is now
    // --gradient-default (2 stops: --bg-elevation-default-layer-0 and
    // --bg-elevation-default-layer-0-gradient), not the flat
    // --bg-elevation-default it used before. check-contrast.ts Rule 4
    // requires every stop token of a gradient referenced via a
    // bg-gradient-* class to appear literally as an fg/bg value in some
    // contrastPairs entry, so the footer toggle row (which sits directly on
    // the panel background, no bg of its own) is declared once per stop
    // rather than once against the old compound token. Both stops verified
    // (WCAG relative-luminance formula, both modes): dark 17.38:1/16.29:1
    // (label) and 8.99:1/8.43:1 (icon); light 15.72:1/17.59:1 (label) and
    // 7.89:1/8.83:1 (icon) — all comfortably above their thresholds.
    contrastPairs: [
      {
        id: "footer toggle label (stop 1)",
        fg: "--text-default-primary",
        bg: "--bg-elevation-default-layer-0",
        minRatio: 4.5,
      },
      {
        id: "footer toggle label (stop 2)",
        fg: "--text-default-primary",
        bg: "--bg-elevation-default-layer-0-gradient",
        minRatio: 4.5,
      },
      {
        id: "footer toggle icon (stop 1)",
        fg: "--text-default-secondary",
        bg: "--bg-elevation-default-layer-0",
        minRatio: 3,
      },
      {
        id: "footer toggle icon (stop 2)",
        fg: "--text-default-secondary",
        bg: "--bg-elevation-default-layer-0-gradient",
        minRatio: 3,
      },
    ],
    notes:
      "Root element is a native <nav aria-label={ariaLabel}> landmark (required prop, no " +
      "default — the exact wording is product/locale-specific and cannot be safely defaulted, " +
      "§5.3). No interaction of its own beyond Tab reaching interactive children in DOM order " +
      "(header/ProductSwitcher → items/submenus → footer collapse toggle) — no custom keyboard " +
      "handling at the Navbar level (§5.2). Collapsed/expanded is a purely visual/layout state, " +
      "not announced via a live region (§5.3) — aria-expanded is used at the item/submenu level " +
      "(NavbarSubmenu), never at the Navbar root, since the root has no ARIA state of its own " +
      "(it's a landmark, not a disclosure widget). Focus management on collapse (an open " +
      "submenu's focus returning to its parent trigger) is implemented by NavbarSubmenu " +
      "reacting to NavbarContext — Navbar only needs to expose collapsed correctly, not " +
      "implement the mechanism itself (§5.2). Width transition: 150ms, Tailwind's default " +
      "easing, with motion-reduce:transition-none — reused from Tooltip's already-proven 150ms " +
      "duration rather than opencti's real 225ms (LeftBar.jsx:438-441), because opencti's " +
      "transition never respects prefers-reduced-motion anywhere in its codebase (repo-wide " +
      "grep confirmed zero matches) — this is the first prefers-reduced-motion implementation " +
      "in the library (§3.5). The built-in footer collapse-toggle row deliberately diverges " +
      "from opencti's real implementation (LeftBar.jsx:812-814, label={t_i18n('Collapse')} " +
      "unconditionally, icon-only swap): a static 'Collapse' label read by AT users while " +
      "already collapsed is misleading (the next action is actually 'expand'), the same class " +
      "of clarity issue already corrected on ProductSwitcher's own chevron — so the label here " +
      "is state-dependent ('Collapse' expanded / 'Expand' collapsed) instead of a static string, " +
      "a disclosed refinement beyond the RFC's literal §4.2 text, not a silent change to an " +
      "arbitrated decision.",
  },
  render() {
    const demoItems = (withSubmenu: boolean) => [
      h(NavbarItem, {
        key: "dashboard",
        icon: h(Icon, { name: "layout-panel-left", size: 16 }),
        "aria-current": "page",
        children: "Dashboard",
      }),
      h(NavbarItem, {
        key: "analyses",
        icon: h(Icon, { name: "chart-bar", size: 16 }),
        children: "Analyses",
      }),
      h(NavbarSeparator, { key: "sep-1" }),
      withSubmenu
        ? h(NavbarSubmenu, {
            key: "knowledge",
            label: "Knowledge",
            icon: h(Icon, { name: "book", size: 16 }),
            defaultOpen: true,
            children: [
              h(NavbarSubmenuItem, { key: "reports", href: "#", children: "Reports" }),
              h(NavbarSubmenuItem, { key: "malware", href: "#", children: "Malware" }),
            ],
          })
        : h(NavbarItem, {
            key: "knowledge",
            icon: h(Icon, { name: "book", size: 16 }),
            children: "Knowledge",
          }),
      h(NavbarSeparator, { key: "sep-2" }),
      h(NavbarItem, {
        key: "settings",
        icon: h(Icon, { name: "settings", size: 16 }),
        children: "Settings",
      }),
    ];

    // Fidelity re-pass #4 point 4: uses the real `ProductSwitcher` (previously
    // a decorative icon-only placeholder) so this demo's "Collapsed" section
    // is the only place that exercises ProductSwitcher's collapsed-mode
    // trigger inside a REAL collapsed Navbar — necessary to empirically
    // verify the logo-as-trigger structure end-to-end, not just in isolation.
    const demoHeader = h(ProductSwitcher, {
      logo: h(Icon, { name: "custom/opencti", size: 20 }),
      label: "More Filigran products",
      options: [
        {
          id: "openaev",
          label: "OpenAEV",
          logo: h(Icon, { name: "custom/openaev", size: 20 }),
          href: "https://example.com/openaev",
        },
      ],
    });

    return h(
      "div",
      { className: "flex gap-6" },
      h(
        "div",
        { className: "flex h-125 flex-col" },
        h(
          "p",
          {
            className:
              "text-content-caption font-content-caption leading-content-caption tracking-content-caption text-default-secondary mb-2",
          },
          "Expanded",
        ),
        h(Navbar, {
          // Distinct aria-label per demo instance — two <nav> landmarks with
          // the SAME accessible name on one page is a real axe landmark-unique
          // violation (WCAG 1.3.1), caught by the conformity test suite. Real
          // consumers only ever render one Navbar per page, so this is purely
          // a showcase-demo concern, not a Navbar API concern.
          "aria-label": "Main navigation (expanded example)",
          header: demoHeader,
          children: demoItems(true),
        }),
      ),
      h(
        "div",
        { className: "flex h-125 flex-col" },
        h(
          "p",
          {
            className:
              "text-content-caption font-content-caption leading-content-caption tracking-content-caption text-default-secondary mb-2",
          },
          "Collapsed",
        ),
        h(Navbar, {
          "aria-label": "Main navigation (collapsed example)",
          header: demoHeader,
          defaultCollapsed: true,
          children: demoItems(true),
        }),
      ),
    );
  },
  examples: [
    "// Uncontrolled — Navbar manages its own collapsed state internally\n" +
      '<Navbar aria-label="Main navigation" header={<ProductSwitcher .../>}>\n' +
      '  <NavbarItem icon={<Icon name="layout-panel-left" size={16} />} aria-current="page">Dashboard</NavbarItem>\n' +
      "  <NavbarSeparator />\n" +
      '  <NavbarSubmenu label="Knowledge" icon={<Icon name="book" size={16} />}>\n' +
      '    <NavbarSubmenuItem href="/reports">Reports</NavbarSubmenuItem>\n' +
      "  </NavbarSubmenu>\n" +
      "</Navbar>",
    "// Controlled collapse, persisted by the consuming product\n" +
      "<Navbar\n" +
      '  aria-label="Main navigation"\n' +
      "  collapsed={collapsed}\n" +
      "  onCollapsedChange={(next) => { setCollapsed(next); localStorage.setItem('navOpen', String(!next)); }}\n" +
      ">\n  ...\n</Navbar>",
    "// Optional footer slot, rendered above the built-in collapse toggle\n" +
      '<Navbar aria-label="Main navigation" footer={<NavbarItem icon={<Icon name="circle-question-mark" size={16} />}>Help</NavbarItem>}>\n  ...\n</Navbar>',
  ],
  variants: ["expanded", "collapsed"],
  sizes: [],
  props: {
    "aria-label":
      "string (required) — accessible landmark name, no default (product/locale-specific)",
    collapsed: "boolean — controlled collapsed state, omit for uncontrolled",
    defaultCollapsed: "boolean — initial collapsed state (uncontrolled), default false",
    onCollapsedChange: "(collapsed: boolean) => void — notifies on footer-toggle-driven changes",
    header: "ReactNode — typically a <ProductSwitcher>, rendered in the 68px header row",
    children: "ReactNode — NavbarItem / NavbarSubmenu / NavbarSeparator content",
    footer:
      "ReactNode — rendered above the built-in collapse toggle (e.g. a help/settings NavbarItem)",
    "NavbarSeparator (named export)":
      "Divider between item groups — a plain <hr>, no props of its own beyond native <hr> attributes",
  },
  // Fidelity re-pass #2 point 9: this is the group's canonical/landing
  // entry (slug "navbar" == id) — see NavbarItem/NavbarSubmenu/
  // ProductSwitcher.meta.ts for the other three tabs on the same page.
  docsGroup: {
    id: "navbar",
    label: "Navbar",
    tabLabel: "Navbar",
  },
};
